/*
 * alarm_manager.c
 */
#include "alarm_manager.h"
#include "config.h"
#include "nvs_storage.h"
#include "buzzer.h"
#include "lcd_i2c.h"
#include "sms_module.h"
#include <math.h>
#include <stdio.h>

typedef enum { ALARM_STATE_CLEARED = 0, ALARM_STATE_RAISED = 1 } alarm_state_t;

static alarm_state_t s_high_state  = ALARM_STATE_CLEARED;
static alarm_state_t s_low_state   = ALARM_STATE_CLEARED;
static alarm_state_t s_fault_state = ALARM_STATE_CLEARED;

static uint16_t s_high_raise_cnt = 0, s_high_clear_cnt = 0;
static uint16_t s_low_raise_cnt  = 0, s_low_clear_cnt  = 0;

void alarm_manager_init(void) {
    // Nothing to do yet; kept for symmetry / future extension.
}

static void notify(uint16_t alarm_id, uint8_t event_type, float temperature,
                    const char *lcd_line, const char *sms_message,
                    uint16_t buzzer_freq, bool start_buzzer) {
    // Log to NVS (SRS1_006/007/010 "Record the event in a log file")
    nvs_storage_append_log(alarm_id, event_type, temperature);

        printf("[ALARM] %s ID=%u temperature=%.1f C\n",
            event_type == LOG_EVENT_RAISED ? "RAISED" : "CLEARED",
            alarm_id, temperature);

    // Display on LCD (SRS1_006/007/010)
    lcd_show_alarm(alarm_id, lcd_line);

    // Send SMS (SRS1_006/007/010) - only on RAISE, not on clear, to limit SMS cost/spam.
    if (event_type == LOG_EVENT_RAISED) {
        sms_module_send(sms_message);
    }

    // Buzzer (SRS1_006/007 "activate the buzzer at a defined frequency")
    if (start_buzzer) {
        buzzer_start(buzzer_freq);
    } else {
        buzzer_stop();
    }
}

// ---------------- High temp: Alarm 1006 ----------------
static void raise_high(float t) {
    s_high_state = ALARM_STATE_RAISED;
    notify(ALARM_ID_HIGH_TEMP, LOG_EVENT_RAISED, t,
           "HIGH TEMP!", "ColdWatch ALARM 1006: High temperature detected",
           BUZZER_FREQ_HIGH_ALARM_HZ, true);
}
static void clear_high(float t) {
    s_high_state = ALARM_STATE_CLEARED;
    notify(ALARM_ID_HIGH_TEMP, LOG_EVENT_CLEARED, t, "", "", 0, false);
}

// ---------------- Low temp: Alarm 1007 ----------------
static void raise_low(float t) {
    s_low_state = ALARM_STATE_RAISED;
    notify(ALARM_ID_LOW_TEMP, LOG_EVENT_RAISED, t,
           "LOW TEMP!", "ColdWatch ALARM 1007: Low temperature detected",
           BUZZER_FREQ_LOW_ALARM_HZ, true);
}
static void clear_low(float t) {
    s_low_state = ALARM_STATE_CLEARED; // SRS1_011
    notify(ALARM_ID_LOW_TEMP, LOG_EVENT_CLEARED, t, "", "", 0, false);
}

// ---------------- Sensor fault: Alarm 1010 ----------------
static void raise_fault(void) {
    s_fault_state = ALARM_STATE_RAISED;
    notify(ALARM_ID_SENSOR_FAULT, LOG_EVENT_RAISED, NAN,
           "SENSOR FAULT!", "ColdWatch ALARM 1010: Temperature sensor fault (check connection)",
           BUZZER_FREQ_FAULT_ALARM_HZ, true);
}
static void clear_fault(void) {
    s_fault_state = ALARM_STATE_CLEARED; // SRS1_011
    notify(ALARM_ID_SENSOR_FAULT, LOG_EVENT_CLEARED, NAN, "", "", 0, false);
}

// ---------------- Main evaluation ----------------
void alarm_manager_update(float temperature, bool temp_valid, bool sensor_fault) {
    coldwatch_config_t *cfg = nvs_storage_get_config();
    uint16_t hyst = cfg->temperatureHysteresis; // SRS1_008: consecutive-sample debounce count

    // --- Sensor fault (SRS1_010) - debounce already applied inside temperature_sensor ---
    if (sensor_fault) {
        s_high_raise_cnt = s_low_raise_cnt = 0; // temperature is not trustworthy while faulted
        s_high_clear_cnt = s_low_clear_cnt = 0;
        if (s_fault_state == ALARM_STATE_CLEARED) raise_fault();
        return; // don't evaluate high/low limits on invalid data
    } else {
        if (s_fault_state == ALARM_STATE_RAISED) clear_fault(); // SRS1_011
    }

    if (!temp_valid) return;

    // --- High / Low temperature evaluation with hysteresis debounce (SRS1_008) ---
    if (temperature > cfg->temperatureHighLimit) {
        s_high_raise_cnt++;
        s_low_raise_cnt = 0; s_low_clear_cnt = 0;
        s_high_clear_cnt = 0;
        if (s_high_state == ALARM_STATE_CLEARED && s_high_raise_cnt >= hyst) raise_high(temperature);

    } else if (temperature < cfg->temperatureLowLimit) {
        s_low_raise_cnt++;
        s_high_raise_cnt = 0; s_high_clear_cnt = 0;
        s_low_clear_cnt = 0;
        if (s_low_state == ALARM_STATE_CLEARED && s_low_raise_cnt >= hyst) raise_low(temperature);

    } else {
        // Back within normal range
        s_high_raise_cnt = 0;
        s_low_raise_cnt = 0;

#if ENABLE_HIGH_AUTO_CLEAR
        if (s_high_state == ALARM_STATE_RAISED) {
            s_high_clear_cnt++;
            if (s_high_clear_cnt >= hyst) clear_high(temperature);
        }
#endif
        if (s_low_state == ALARM_STATE_RAISED) { // SRS1_011 (mandatory auto-clear)
            s_low_clear_cnt++;
            if (s_low_clear_cnt >= hyst) clear_low(temperature);
        }
    }
}

void alarm_manager_refresh_outputs(const char *sensor_type_name, float last_temperature, bool last_temp_valid) {
    // Priority: sensor fault > high temp > low temp > normal display
    if (s_fault_state == ALARM_STATE_RAISED) {
        lcd_show_alarm(ALARM_ID_SENSOR_FAULT, "SENSOR FAULT!");
    } else if (s_high_state == ALARM_STATE_RAISED) {
        lcd_show_alarm(ALARM_ID_HIGH_TEMP, "HIGH TEMP!");
    } else if (s_low_state == ALARM_STATE_RAISED) {
        lcd_show_alarm(ALARM_ID_LOW_TEMP, "LOW TEMP!");
    } else {
        lcd_show_normal(sensor_type_name, last_temperature, last_temp_valid);
    }

    buzzer_update();
}

bool alarm_manager_is_high_active(void)  { return s_high_state  == ALARM_STATE_RAISED; }
bool alarm_manager_is_low_active(void)   { return s_low_state   == ALARM_STATE_RAISED; }
bool alarm_manager_is_fault_active(void) { return s_fault_state == ALARM_STATE_RAISED; }

/*
 * alarm_manager.c
 */
#include "alarm_manager.h"
#include "config.h"
#include "nvs_storage.h"
#include "buzzer.h"
#include "lcd_i2c.h"
#include "sms_module.h"
#include "esp_timer.h"
#include <math.h>
#include <stdio.h>

typedef enum { ALARM_STATE_CLEARED = 0, ALARM_STATE_RAISED = 1 } alarm_state_t;

static alarm_state_t s_high_state  = ALARM_STATE_CLEARED;
static alarm_state_t s_low_state   = ALARM_STATE_CLEARED;
static alarm_state_t s_fault_state = ALARM_STATE_CLEARED;

static uint16_t s_high_raise_cnt = 0, s_high_clear_cnt = 0;
static uint16_t s_low_raise_cnt  = 0, s_low_clear_cnt  = 0;

// SRS2_006/007/010: humidity alarm state (mirrors the temperature state above)
static alarm_state_t s_humidity_high_state  = ALARM_STATE_CLEARED;
static alarm_state_t s_humidity_low_state   = ALARM_STATE_CLEARED;
static alarm_state_t s_humidity_fault_state = ALARM_STATE_CLEARED;

static uint16_t s_humidity_high_raise_cnt = 0, s_humidity_high_clear_cnt = 0;
static uint16_t s_humidity_low_raise_cnt  = 0, s_humidity_low_clear_cnt  = 0;

// Main power-supply loss state (GPIO34 detection, see components/power_source)
static alarm_state_t s_power_state = ALARM_STATE_CLEARED; // CLEARED = mains power OK

// SRS3_005/006: battery low / critical state (see components/power_source)
static alarm_state_t s_battery_low_state      = ALARM_STATE_CLEARED;
static alarm_state_t s_battery_critical_state = ALARM_STATE_CLEARED;
static uint16_t s_battery_low_raise_cnt = 0, s_battery_low_clear_cnt = 0;
static uint16_t s_battery_critical_raise_cnt = 0, s_battery_critical_clear_cnt = 0;

void alarm_manager_init(void) {
    // Nothing to do yet; kept for symmetry / future extension.
}

static void notify(uint16_t alarm_id, uint8_t event_type, float temperature,
                    const char *lcd_line, const char *sms_message,
                    uint16_t buzzer_freq, bool start_buzzer) {
    // Log to NVS (SRS1_006/007/010 "Record the event in a log file")
    nvs_storage_append_log(alarm_id, event_type, temperature);

        printf("[ALARM] %s ID=%u temperature=%.1f C\n",
            event_type == LOG_EVENT_RAISED ? "RAISED" : "CLEARED",
            alarm_id, temperature);

    // Display on LCD (SRS1_006/007/010)
    lcd_show_alarm(alarm_id, lcd_line);

    // Send SMS (SRS1_006/007/010) - only on RAISE, not on clear, to limit SMS cost/spam.
    if (event_type == LOG_EVENT_RAISED) {
        sms_module_send(sms_message);
    }

    // Buzzer (SRS1_006/007 "activate the buzzer at a defined frequency")
    if (start_buzzer) {
        buzzer_start(buzzer_freq);
    } else {
        buzzer_stop();
    }
}

// ---------------- High temp: Alarm 1006 ----------------
static void raise_high(float t) {
    s_high_state = ALARM_STATE_RAISED;
    notify(ALARM_ID_HIGH_TEMP, LOG_EVENT_RAISED, t,
           "HIGH TEMP!", "ColdWatch ALARM 1006: High temperature detected",
           BUZZER_FREQ_HIGH_ALARM_HZ, true);
}
static void clear_high(float t) {
    s_high_state = ALARM_STATE_CLEARED;
    notify(ALARM_ID_HIGH_TEMP, LOG_EVENT_CLEARED, t, "", "", 0, false);
}

// ---------------- Low temp: Alarm 1007 ----------------
static void raise_low(float t) {
    s_low_state = ALARM_STATE_RAISED;
    notify(ALARM_ID_LOW_TEMP, LOG_EVENT_RAISED, t,
           "LOW TEMP!", "ColdWatch ALARM 1007: Low temperature detected",
           BUZZER_FREQ_LOW_ALARM_HZ, true);
}
static void clear_low(float t) {
    s_low_state = ALARM_STATE_CLEARED; // SRS1_011
    notify(ALARM_ID_LOW_TEMP, LOG_EVENT_CLEARED, t, "", "", 0, false);
}

// ---------------- Sensor fault: Alarm 1010 ----------------
static void raise_fault(void) {
    s_fault_state = ALARM_STATE_RAISED;
    notify(ALARM_ID_SENSOR_FAULT, LOG_EVENT_RAISED, NAN,
           "SENSOR FAULT!", "ColdWatch ALARM 1010: Temperature sensor fault (check connection)",
           BUZZER_FREQ_FAULT_ALARM_HZ, true);
}
static void clear_fault(void) {
    s_fault_state = ALARM_STATE_CLEARED; // SRS1_011
    notify(ALARM_ID_SENSOR_FAULT, LOG_EVENT_CLEARED, NAN, "", "", 0, false);
}

// ---------------- High humidity: Alarm 2006 ----------------
static void raise_humidity_high(float h) {
    s_humidity_high_state = ALARM_STATE_RAISED;
    notify(ALARM_ID_HIGH_HUMIDITY, LOG_EVENT_RAISED, h,
           "HIGH HUMIDITY!", "ColdWatch ALARM 2006: High humidity detected",
           BUZZER_FREQ_HIGH_HUMIDITY_ALARM_HZ, true);
}
static void clear_humidity_high(float h) {
    s_humidity_high_state = ALARM_STATE_CLEARED;
    notify(ALARM_ID_HIGH_HUMIDITY, LOG_EVENT_CLEARED, h, "", "", 0, false);
}

// ---------------- Low humidity: Alarm 2007 ----------------
static void raise_humidity_low(float h) {
    s_humidity_low_state = ALARM_STATE_RAISED;
    notify(ALARM_ID_LOW_HUMIDITY, LOG_EVENT_RAISED, h,
           "LOW HUMIDITY!", "ColdWatch ALARM 2007: Low humidity detected",
           BUZZER_FREQ_LOW_HUMIDITY_ALARM_HZ, true);
}
static void clear_humidity_low(float h) {
    s_humidity_low_state = ALARM_STATE_CLEARED; // SRS2_011
    notify(ALARM_ID_LOW_HUMIDITY, LOG_EVENT_CLEARED, h, "", "", 0, false);
}

// ---------------- Humidity sensor fault: Alarm 2010 ----------------
static void raise_humidity_fault(void) {
    s_humidity_fault_state = ALARM_STATE_RAISED;
    notify(ALARM_ID_HUMIDITY_SENSOR_FAULT, LOG_EVENT_RAISED, NAN,
           "HUM SENSOR FAULT", "ColdWatch ALARM 2010: Humidity sensor fault (check connection)",
           BUZZER_FREQ_HUMIDITY_FAULT_ALARM_HZ, true);
}
static void clear_humidity_fault(void) {
    s_humidity_fault_state = ALARM_STATE_CLEARED; // SRS2_011
    notify(ALARM_ID_HUMIDITY_SENSOR_FAULT, LOG_EVENT_CLEARED, NAN, "", "", 0, false);
}

// ---------------- Main power supply lost/restored: Alarm 3001 (SRS3_001/003) ----------------
static void raise_power_lost(void) {
    s_power_state = ALARM_STATE_RAISED;
    notify(ALARM_ID_POWER_SOURCE, LOG_EVENT_RAISED, NAN,
           "ON BATTERY!", "ColdWatch ALARM 3001: Main power lost - running on internal battery",
           BUZZER_FREQ_POWER_ALARM_HZ, true);
}
static void clear_power_restored(void) {
    s_power_state = ALARM_STATE_CLEARED;
    notify(ALARM_ID_POWER_SOURCE, LOG_EVENT_CLEARED, NAN,
           "", "ColdWatch: Main power supply restored", 0, false);
}

// SRS3_001/003: debouncing is already applied upstream in power_source_update();
// we simply react to confirmed transitions here.
void alarm_manager_update_power(bool on_battery) {
    if (on_battery && s_power_state == ALARM_STATE_CLEARED) {
        raise_power_lost();          // SRS3_001
    } else if (!on_battery && s_power_state == ALARM_STATE_RAISED) {
        clear_power_restored();      // SRS3_003
    }
}

// ---------------- Low battery: Alarm 3005 (SRS3_005) ----------------
static void raise_battery_low(uint8_t percent) {
    s_battery_low_state = ALARM_STATE_RAISED;
    char msg[64];
    snprintf(msg, sizeof(msg), "ColdWatch ALARM 3005: Low battery (%u%%)", percent);
    notify(ALARM_ID_LOW_BATTERY, LOG_EVENT_RAISED, (float)percent,
           "LOW BATTERY!", msg, BUZZER_FREQ_LOW_BATTERY_ALARM_HZ, true);
}
static void clear_battery_low(uint8_t percent) {
    s_battery_low_state = ALARM_STATE_CLEARED;
    notify(ALARM_ID_LOW_BATTERY, LOG_EVENT_CLEARED, (float)percent, "", "", 0, false);
}

// ---------------- Critical battery: Alarm 3006 (SRS3_006) ----------------
static void raise_battery_critical(uint8_t percent, float voltage, bool on_battery,
                                    float last_temperature, bool last_temp_valid,
                                    float last_humidity, bool last_humidity_valid) {
    s_battery_critical_state = ALARM_STATE_RAISED;
    char msg[64];
    snprintf(msg, sizeof(msg), "ColdWatch ALARM 3006: CRITICAL battery (%u%%) - data saved", percent);
    notify(ALARM_ID_CRITICAL_BATTERY, LOG_EVENT_RAISED, (float)percent,
           "BATT CRITICAL!", msg, BUZZER_FREQ_CRITICAL_BATTERY_ALARM_HZ, true);

    // SRS3_006: save important data in memory (NVS) before a possible
    // imminent power-off/brown-out.
    coldwatch_emergency_snapshot_t snap = {
        .timestampMs        = esp_timer_get_time() / 1000,
        .temperature         = last_temperature,
        .temperatureValid    = last_temp_valid ? 1 : 0,
        .humidity            = last_humidity,
        .humidityValid       = last_humidity_valid ? 1 : 0,
        .batteryVoltage      = voltage,
        .batteryPercentage   = percent,
        .onBattery           = on_battery ? 1 : 0,
    };
    nvs_storage_save_emergency_snapshot(&snap);
}
static void clear_battery_critical(uint8_t percent) {
    s_battery_critical_state = ALARM_STATE_CLEARED;
    notify(ALARM_ID_CRITICAL_BATTERY, LOG_EVENT_CLEARED, (float)percent, "", "", 0, false);
}

// SRS3_004/005/006: battery evaluation with consecutive-sample debounce,
// mirroring the temperature/humidity hysteresis pattern above.
void alarm_manager_update_battery(float voltage, uint8_t percent, bool on_battery,
                                   float last_temperature, bool last_temp_valid,
                                   float last_humidity, bool last_humidity_valid) {
    // --- Critical battery (SRS3_006) ---
    if (percent <= BATTERY_CRITICAL_PERCENT) {
        s_battery_critical_raise_cnt++;
        s_battery_critical_clear_cnt = 0;
        if (s_battery_critical_state == ALARM_STATE_CLEARED &&
            s_battery_critical_raise_cnt >= BATTERY_CRITICAL_HYSTERESIS_CNT) {
            raise_battery_critical(percent, voltage, on_battery,
                                    last_temperature, last_temp_valid,
                                    last_humidity, last_humidity_valid);
        }
    } else {
        s_battery_critical_raise_cnt = 0;
        if (s_battery_critical_state == ALARM_STATE_RAISED) {
            s_battery_critical_clear_cnt++;
            if (s_battery_critical_clear_cnt >= BATTERY_CRITICAL_HYSTERESIS_CNT) {
                clear_battery_critical(percent);
            }
        }
    }

    // --- Low battery (SRS3_005) ---
    if (percent <= BATTERY_LOW_PERCENT) {
        s_battery_low_raise_cnt++;
        s_battery_low_clear_cnt = 0;
        if (s_battery_low_state == ALARM_STATE_CLEARED &&
            s_battery_low_raise_cnt >= BATTERY_LOW_HYSTERESIS_CNT) {
            raise_battery_low(percent);
        }
    } else {
        s_battery_low_raise_cnt = 0;
        if (s_battery_low_state == ALARM_STATE_RAISED) {
            s_battery_low_clear_cnt++;
            if (s_battery_low_clear_cnt >= BATTERY_LOW_HYSTERESIS_CNT) {
                clear_battery_low(percent);
            }
        }
    }
}

// ---------------- Main evaluation ----------------
void alarm_manager_update(float temperature, bool temp_valid, bool sensor_fault) {
    coldwatch_config_t *cfg = nvs_storage_get_config();
    uint16_t hyst = cfg->temperatureHysteresis; // SRS1_008: consecutive-sample debounce count

    // --- Sensor fault (SRS1_010) - debounce already applied inside temperature_sensor ---
    if (sensor_fault) {
        s_high_raise_cnt = s_low_raise_cnt = 0; // temperature is not trustworthy while faulted
        s_high_clear_cnt = s_low_clear_cnt = 0;
        if (s_fault_state == ALARM_STATE_CLEARED) raise_fault();
        return; // don't evaluate high/low limits on invalid data
    } else {
        if (s_fault_state == ALARM_STATE_RAISED) clear_fault(); // SRS1_011
    }

    if (!temp_valid) return;

    // --- High / Low temperature evaluation with hysteresis debounce (SRS1_008) ---
    if (temperature > cfg->temperatureHighLimit) {
        s_high_raise_cnt++;
        s_low_raise_cnt = 0; s_low_clear_cnt = 0;
        s_high_clear_cnt = 0;
        if (s_high_state == ALARM_STATE_CLEARED && s_high_raise_cnt >= hyst) raise_high(temperature);

    } else if (temperature < cfg->temperatureLowLimit) {
        s_low_raise_cnt++;
        s_high_raise_cnt = 0; s_high_clear_cnt = 0;
        s_low_clear_cnt = 0;
        if (s_low_state == ALARM_STATE_CLEARED && s_low_raise_cnt >= hyst) raise_low(temperature);

    } else {
        // Back within normal range
        s_high_raise_cnt = 0;
        s_low_raise_cnt = 0;

#if ENABLE_HIGH_AUTO_CLEAR
        if (s_high_state == ALARM_STATE_RAISED) {
            s_high_clear_cnt++;
            if (s_high_clear_cnt >= hyst) clear_high(temperature);
        }
#endif
        if (s_low_state == ALARM_STATE_RAISED) { // SRS1_011 (mandatory auto-clear)
            s_low_clear_cnt++;
            if (s_low_clear_cnt >= hyst) clear_low(temperature);
        }
    }
}

// ---------------- Main evaluation (humidity, SRS2_006/007/008/010/011) ----------------
void alarm_manager_update_humidity(float humidity, bool humidity_valid, bool sensor_fault) {
    coldwatch_config_t *cfg = nvs_storage_get_config();
    uint16_t hyst = cfg->humidityHysteresis; // SRS2_008: consecutive-sample debounce count

    // --- Sensor fault (SRS2_010) - debounce already applied inside humidity_sensor ---
    if (sensor_fault) {
        s_humidity_high_raise_cnt = s_humidity_low_raise_cnt = 0; // humidity is not trustworthy while faulted
        s_humidity_high_clear_cnt = s_humidity_low_clear_cnt = 0;
        if (s_humidity_fault_state == ALARM_STATE_CLEARED) raise_humidity_fault();
        return; // don't evaluate high/low limits on invalid data
    } else {
        if (s_humidity_fault_state == ALARM_STATE_RAISED) clear_humidity_fault(); // SRS2_011
    }

    if (!humidity_valid) return;

    // --- High / Low humidity evaluation with hysteresis debounce (SRS2_008) ---
    if (humidity > cfg->humidityHighLimit) {
        s_humidity_high_raise_cnt++;
        s_humidity_low_raise_cnt = 0; s_humidity_low_clear_cnt = 0;
        s_humidity_high_clear_cnt = 0;
        if (s_humidity_high_state == ALARM_STATE_CLEARED && s_humidity_high_raise_cnt >= hyst) raise_humidity_high(humidity);

    } else if (humidity < cfg->humidityLowLimit) {
        s_humidity_low_raise_cnt++;
        s_humidity_high_raise_cnt = 0; s_humidity_high_clear_cnt = 0;
        s_humidity_low_clear_cnt = 0;
        if (s_humidity_low_state == ALARM_STATE_CLEARED && s_humidity_low_raise_cnt >= hyst) raise_humidity_low(humidity);

    } else {
        // Back within normal range
        s_humidity_high_raise_cnt = 0;
        s_humidity_low_raise_cnt = 0;

#if ENABLE_HIGH_AUTO_CLEAR
        if (s_humidity_high_state == ALARM_STATE_RAISED) {
            s_humidity_high_clear_cnt++;
            if (s_humidity_high_clear_cnt >= hyst) clear_humidity_high(humidity);
        }
#endif
        if (s_humidity_low_state == ALARM_STATE_RAISED) { // SRS2_011 (mandatory auto-clear)
            s_humidity_low_clear_cnt++;
            if (s_humidity_low_clear_cnt >= hyst) clear_humidity_low(humidity);
        }
    }
}

void alarm_manager_refresh_outputs(const char *sensor_type_name, float last_temperature, bool last_temp_valid,
                                    const char *humidity_sensor_type_name, float last_humidity, bool last_humidity_valid,
                                    const char *power_source_name, float battery_voltage, uint8_t battery_percentage,
                                    bool battery_reading_is_accurate) {
    // Priority: critical battery > power lost > low battery > temp sensor fault
    //           > humidity sensor fault > high temp > low temp > high humidity
    //           > low humidity > normal display
    if (s_battery_critical_state == ALARM_STATE_RAISED) {
        lcd_show_alarm(ALARM_ID_CRITICAL_BATTERY, "BATT CRITICAL!");
    } else if (s_power_state == ALARM_STATE_RAISED) {
        lcd_show_alarm(ALARM_ID_POWER_SOURCE, "ON BATTERY!");
    } else if (s_battery_low_state == ALARM_STATE_RAISED) {
        lcd_show_alarm(ALARM_ID_LOW_BATTERY, "LOW BATTERY!");
    } else if (s_fault_state == ALARM_STATE_RAISED) {
        lcd_show_alarm(ALARM_ID_SENSOR_FAULT, "SENSOR FAULT!");
    } else if (s_humidity_fault_state == ALARM_STATE_RAISED) {
        lcd_show_alarm(ALARM_ID_HUMIDITY_SENSOR_FAULT, "HUM SENSOR FAULT");
    } else if (s_high_state == ALARM_STATE_RAISED) {
        lcd_show_alarm(ALARM_ID_HIGH_TEMP, "HIGH TEMP!");
    } else if (s_low_state == ALARM_STATE_RAISED) {
        lcd_show_alarm(ALARM_ID_LOW_TEMP, "LOW TEMP!");
    } else if (s_humidity_high_state == ALARM_STATE_RAISED) {
        lcd_show_alarm(ALARM_ID_HIGH_HUMIDITY, "HIGH HUMIDITY!");
    } else if (s_humidity_low_state == ALARM_STATE_RAISED) {
        lcd_show_alarm(ALARM_ID_LOW_HUMIDITY, "LOW HUMIDITY!");
    } else {
        lcd_show_normal(sensor_type_name, last_temperature, last_temp_valid,
                         humidity_sensor_type_name, last_humidity, last_humidity_valid,
                         power_source_name, battery_voltage, battery_percentage,
                         battery_reading_is_accurate);
    }

    buzzer_update();
}

bool alarm_manager_is_high_active(void)  { return s_high_state  == ALARM_STATE_RAISED; }
bool alarm_manager_is_low_active(void)   { return s_low_state   == ALARM_STATE_RAISED; }
bool alarm_manager_is_fault_active(void) { return s_fault_state == ALARM_STATE_RAISED; }

bool alarm_manager_is_humidity_high_active(void)  { return s_humidity_high_state  == ALARM_STATE_RAISED; }
bool alarm_manager_is_humidity_low_active(void)   { return s_humidity_low_state   == ALARM_STATE_RAISED; }
bool alarm_manager_is_humidity_fault_active(void) { return s_humidity_fault_state == ALARM_STATE_RAISED; }

bool alarm_manager_is_power_lost_active(void) { return s_power_state == ALARM_STATE_RAISED; }

bool alarm_manager_is_battery_low_active(void)      { return s_battery_low_state      == ALARM_STATE_RAISED; }
bool alarm_manager_is_battery_critical_active(void) { return s_battery_critical_state == ALARM_STATE_RAISED; }

/*
 * alarm_manager.h
 * Implements SRS1_006, SRS1_007, SRS1_008, SRS1_010, SRS1_011.
 *
 * Debounce/hysteresis strategy (SRS1_008):
 *  An alarm condition (or its clearing) must be observed for
 *  'temperatureHysteresis' CONSECUTIVE samples before the firmware
 *  acts on it. This filters noise/transient spikes.
 *
 * Auto-clear strategy (SRS1_011):
 *  Alarm 1007 (low temp) and Alarm 1010 (sensor fault) are cleared
 *  automatically by firmware once the condition is resolved for the
 *  debounce window. Alarm 1006 (high temp) is also auto-cleared using
 *  the same hysteresis window for consistency; set ENABLE_HIGH_AUTO_CLEAR
 *  to 0 below if your process requires a manual acknowledgement instead.
 */
#ifndef COLDWATCH_ALARM_MANAGER_H
#define COLDWATCH_ALARM_MANAGER_H

#include <stdint.h>
#include <stdbool.h>

#define ENABLE_HIGH_AUTO_CLEAR 1

void alarm_manager_init(void);

// Call once per sensor sample cycle.
void alarm_manager_update(float temperature, bool temp_valid, bool sensor_fault);

// Drives the LCD / buzzer according to current alarm priority.
// Call periodically (independent of the sample rate).
void alarm_manager_refresh_outputs(const char *sensor_type_name, float last_temperature, bool last_temp_valid);

bool alarm_manager_is_high_active(void);
bool alarm_manager_is_low_active(void);
bool alarm_manager_is_fault_active(void);

#endif // COLDWATCH_ALARM_MANAGER_H

/*
 * alarm_manager.h
 * Implements SRS1_006, SRS1_007, SRS1_008, SRS1_010, SRS1_011 (temperature),
 * SRS2_006, SRS2_007, SRS2_008, SRS2_010, SRS2_011 (humidity), and
 * SRS3_001, SRS3_003, SRS3_005, SRS3_006 (power/battery).
 *
 * Debounce/hysteresis strategy (SRS1_008 / SRS2_008):
 *  An alarm condition (or its clearing) must be observed for
 *  'temperatureHysteresis' / 'humidityHysteresis' CONSECUTIVE samples
 *  before the firmware acts on it. This filters noise/transient spikes.
 *  The battery low/critical alarms (SRS3_005/006) use the same
 *  consecutive-sample strategy via BATTERY_LOW_HYSTERESIS_CNT /
 *  BATTERY_CRITICAL_HYSTERESIS_CNT (config.h).
 *
 * Auto-clear strategy (SRS1_011 / SRS2_011):
 *  Alarm 1007 (low temp), 1010 (temp sensor fault), 2007 (low humidity) and
 *  2010 (humidity sensor fault) are cleared automatically by firmware once
 *  the condition is resolved for the debounce window. Alarms 1006 and 2006
 *  (high temp / high humidity) are also auto-cleared using the same
 *  hysteresis window for consistency; set ENABLE_HIGH_AUTO_CLEAR to 0
 *  below if your process requires a manual acknowledgement instead.
 *  (Note: SRS2_011's text says "clear the alarm 1006 & 2010" - taken as a
 *  literal reference to the existing SRS1_011 auto-clear behavior plus
 *  the new 2010 humidity fault alarm; 2006/2007 are auto-cleared the same
 *  way for consistency.)
 *  Alarm 3001 (power lost), 3005 (low battery) and 3006 (critical battery)
 *  are likewise auto-cleared once the debounced condition resolves.
 */
#ifndef COLDWATCH_ALARM_MANAGER_H
#define COLDWATCH_ALARM_MANAGER_H

#include <stdint.h>
#include <stdbool.h>

#define ENABLE_HIGH_AUTO_CLEAR 1

void alarm_manager_init(void);

// Call once per temperature sample cycle.
void alarm_manager_update(float temperature, bool temp_valid, bool sensor_fault);

// Call once per humidity sample cycle (SRS2_006/007/008/010/011).
void alarm_manager_update_humidity(float humidity, bool humidity_valid, bool sensor_fault);

// Call once per power-source sample cycle. 'on_battery' should already be
// debounced (see components/power_source, power_source_update()). Raises
// ALARM_ID_POWER_SOURCE when mains power is lost (SRS3_001), clears it
// when restored (SRS3_003).
void alarm_manager_update_power(bool on_battery);

// Call once per power-source sample cycle (SRS3_004/005/006). 'voltage'
// and 'percent' come from power_source_get_battery_voltage()/percentage().
// 'on_battery' and the last known temperature/humidity readings are only
// used to fill in the SRS3_006 emergency snapshot if/when the critical
// threshold is reached.
void alarm_manager_update_battery(float voltage, uint8_t percent, bool on_battery,
                                   float last_temperature, bool last_temp_valid,
                                   float last_humidity, bool last_humidity_valid);

// Drives the LCD / buzzer according to current alarm priority.
// Call periodically (independent of the sample rate).
void alarm_manager_refresh_outputs(const char *sensor_type_name, float last_temperature, bool last_temp_valid,
                                    const char *humidity_sensor_type_name, float last_humidity, bool last_humidity_valid,
                                    const char *power_source_name, float battery_voltage, uint8_t battery_percentage,
                                    bool battery_reading_is_accurate);

bool alarm_manager_is_high_active(void);
bool alarm_manager_is_low_active(void);
bool alarm_manager_is_fault_active(void);

bool alarm_manager_is_humidity_high_active(void);
bool alarm_manager_is_humidity_low_active(void);
bool alarm_manager_is_humidity_fault_active(void);

bool alarm_manager_is_power_lost_active(void);
bool alarm_manager_is_battery_low_active(void);
bool alarm_manager_is_battery_critical_active(void);

#endif // COLDWATCH_ALARM_MANAGER_H

/*
 * config.h
 * Central configuration for ColdWatch firmware (ESP32 / ESP-IDF, pure C).
 * Maps to: SRS1_001..SRS1_011, SRS2_001..SRS2_011
 */
#ifndef COLDWATCH_CONFIG_H
#define COLDWATCH_CONFIG_H

#include "driver/gpio.h"
#include "esp_adc/adc_oneshot.h"

// ============================================================
// SRS1_009: Sensor type support (multiple sensor types on LCD)
// Plain integer macros so they can be used in #if preprocessor checks.
// ============================================================
#define SENSOR_TYPE_DS18B20     0   // OneWire digital sensor, typ. +-0.5C accuracy
#define SENSOR_TYPE_ANALOG_LM35 1   // Analog LM35, 10mV/C, via ESP32 ADC (SRS1_001)
#define SENSOR_TYPE_ANALOG_NTC  2   // Analog NTC thermistor via ESP32 ADC (SRS1_001)

// Select the physically connected sensor here (compile-time selection).
// DS18B20 is recommended to meet the +-1C accuracy target (SRS1_005).
#define ACTIVE_SENSOR_TYPE   SENSOR_TYPE_DS18B20

// ============================================================
// Pin assignments (ESP32 DevKitC style boards)
// ============================================================
#define ONE_WIRE_BUS_GPIO     GPIO_NUM_4     // DS18B20 data pin (needs 4.7k pull-up to 3.3V)
#define ANALOG_TEMP_ADC_CHAN  ADC_CHANNEL_6  // GPIO34 - analog sensor (LM35/NTC) - SRS1_001
#define BUZZER_GPIO           GPIO_NUM_25    // Buzzer, driven via LEDC PWM
#define ACK_BUTTON_GPIO       GPIO_NUM_27    // Push button (to GND, internal pull-up) - silence buzzer

// DHT11 temperature/humidity sensor (optional, independent of the main
// cold-chain sensor above). Needs a 4.7k-10k pull-up to 3.3V on the data
// line (most DHT11 breakout boards already include one on-board).
// SRS2_001: humidity is read via the DHT11's proprietary single-wire
// protocol (bit-banged GPIO) - documented assumption, since the requirement
// text left the protocol TBD ("GPIO or any other protocol").
#define ENABLE_DHT11          1
#define DHT11_GPIO            GPIO_NUM_18
#define DHT11_SAMPLE_INTERVAL_MS  2000   // DHT11 max sample rate is ~1Hz

// SRS2_009: only one humidity sensor type is currently implemented (DHT11),
// but the getter function pattern mirrors SRS1_009 so more types could be
// added later the same way ACTIVE_SENSOR_TYPE works for temperature.

// ILI9341 TFT display over SPI. These pins avoid the sensor and modem pins.
#define LCD_SPI_SCLK_GPIO       GPIO_NUM_14
#define LCD_SPI_MOSI_GPIO       GPIO_NUM_13
#define LCD_SPI_MISO_GPIO       GPIO_NUM_12
#define LCD_SPI_CS_GPIO         GPIO_NUM_15
#define LCD_SPI_DC_GPIO         GPIO_NUM_2
#define LCD_SPI_RESET_GPIO      (-1)  // TFT RESET is connected to ESP32 EN
#define LCD_SPI_BACKLIGHT_GPIO  GPIO_NUM_21
#define LCD_WIDTH               240
#define LCD_HEIGHT              320

// UART for SIM800L / SIM900 GSM module
#define GSM_UART_PORT         UART_NUM_2
#define GSM_UART_TX_GPIO      GPIO_NUM_17
#define GSM_UART_RX_GPIO      GPIO_NUM_16
#define GSM_BAUD_RATE         9600
#define SMS_SEND_TIMEOUT_MS   5000

// ============================================================
// SRS1_002 / SRS1_003 / SRS1_004 / SRS1_008: default configurable properties
// Persisted at runtime in ESP32 NVS (see nvs_storage.c) and changeable via
// the serial console (see main.c "SET ..." commands).
// ============================================================
    #define DEFAULT_TEMP_HIGH_LIMIT      30.0f   // SRS1_002
#define DEFAULT_TEMP_LOW_LIMIT        0.0f   // SRS1_003
#define DEFAULT_TEMP_RESOLUTION       0.1f   // SRS1_004 (deg C per step)

// SRS1_008: temperatureHysteresis = 30
// Interpretation: number of CONSECUTIVE samples for which the temperature
// must remain beyond (or back within) a limit before the firmware accepts
// the change as real (debounce / anti-chatter filter), i.e. a "count" of
// samples, not a temperature delta. At a 1s sample rate this is a 30s
// confirmation window. (Documented assumption - spec text is ambiguous.)
#define DEFAULT_TEMP_HYSTERESIS_CNT   3

// ============================================================
// SRS2_002 / SRS2_003 / SRS2_004 / SRS2_008: humidity configurable properties
// Persisted at runtime in ESP32 NVS (see nvs_storage.c) and changeable via
// the serial console (see main.c "SET HUM..." commands).
// ============================================================
#define DEFAULT_HUMIDITY_HIGH_LIMIT   100.0f  // SRS2_002
#define DEFAULT_HUMIDITY_LOW_LIMIT      0.0f  // SRS2_003
#define DEFAULT_HUMIDITY_RESOLUTION      0.1f // SRS2_004 (%RH per step)

// SRS2_008: humidityHysteresis = 30 (consecutive-sample debounce count,
// same interpretation/assumption as SRS1_008 for temperature).
#define DEFAULT_HUMIDITY_HYSTERESIS_CNT 30

// ============================================================
// Alarm IDs
// ============================================================
#define ALARM_ID_HIGH_TEMP     1006   // SRS1_006
#define ALARM_ID_LOW_TEMP      1007   // SRS1_007
#define ALARM_ID_SENSOR_FAULT  1010   // SRS1_010
#define ALARM_ID_HIGH_HUMIDITY        2006   // SRS2_006
#define ALARM_ID_LOW_HUMIDITY         2007   // SRS2_007
#define ALARM_ID_HUMIDITY_SENSOR_FAULT 2010  // SRS2_010

// ============================================================
// Buzzer (SRS1_006 / SRS1_007: "activate buzzer at a defined frequency")
// ============================================================
#define BUZZER_LEDC_TIMER       LEDC_TIMER_0
#define BUZZER_LEDC_CHANNEL     LEDC_CHANNEL_0
#define BUZZER_LEDC_MODE        LEDC_LOW_SPEED_MODE
#define BUZZER_LEDC_DUTY_RES    LEDC_TIMER_8_BIT   // 0-255 duty range
#define BUZZER_LEDC_DUTY_ON     128                // 50% duty = audible tone

#define BUZZER_FREQ_HIGH_ALARM_HZ   2500
#define BUZZER_FREQ_LOW_ALARM_HZ    2000
#define BUZZER_FREQ_FAULT_ALARM_HZ  1500
#define BUZZER_BEEP_ON_MS            300
#define BUZZER_BEEP_OFF_MS           700

// SRS2_006 / SRS2_007: distinct tones for humidity alarms so they can be
// told apart from temperature alarms by ear.
#define BUZZER_FREQ_HIGH_HUMIDITY_ALARM_HZ   2700
#define BUZZER_FREQ_LOW_HUMIDITY_ALARM_HZ    2200
#define BUZZER_FREQ_HUMIDITY_FAULT_ALARM_HZ  1700

// ============================================================
// SRS1_010: Sensor fault detection thresholds
// ============================================================
#define SENSOR_FAULT_CONSEC_READS     5     // consecutive bad reads -> declare fault
#define SENSOR_RECOVER_CONSEC_READS   5     // consecutive good reads -> clear fault (SRS1_011)
#define DS18B20_DISCONNECT_VALUE   -127.0f  // no presence pulse / bad CRC sentinel
#define DS18B20_POWERON_RESET_VALUE 85.0f   // DS18B20 power-on-reset garbage value
#define ANALOG_OPEN_LOW_RAW           20    // raw ADC (0-4095, 12-bit) below this => broken/open wire
#define ANALOG_OPEN_HIGH_RAW        4075    // raw ADC above this => shorted/open wire

// ============================================================
// SRS2_010: Humidity (DHT11) sensor fault detection.
// Documented assumption: a "connection problem" is detected the same way
// as the DS18B20 (SRS1_010) - i.e. the sensor fails to respond to the
// handshake, or its checksum doesn't validate (electrical noise / bad
// wiring), confirmed over several consecutive reads to avoid false
// positives from a single missed 1-second timing window.
// ============================================================
#define HUMIDITY_FAULT_CONSEC_READS    5    // consecutive bad reads -> declare fault (SRS2_010)
#define HUMIDITY_RECOVER_CONSEC_READS  5    // consecutive good reads -> clear fault (SRS2_011)

// ============================================================
// SMS destination
// ============================================================
#define SMS_DESTINATION_NUMBER  "+10000000000"   // TODO: set the real destination number

// ============================================================
// Sampling
// ============================================================
#define SENSOR_SAMPLE_INTERVAL_MS   1000
#define LCD_REFRESH_INTERVAL_MS      500
#define BUZZER_UPDATE_INTERVAL_MS     50

#endif // COLDWATCH_CONFIG_H

/*
 * config.h
 * Central configuration for ColdWatch firmware (ESP32 / ESP-IDF, pure C).
 * Maps to: SRS1_001..SRS1_011, SRS2_001..SRS2_011
 */
#ifndef COLDWATCH_CONFIG_H
#define COLDWATCH_CONFIG_H

#include "driver/gpio.h"
#include "esp_adc/adc_oneshot.h"

// ============================================================
// SRS1_009: Sensor type support (multiple sensor types on LCD)
// Plain integer macros so they can be used in #if preprocessor checks.
// ============================================================
#define SENSOR_TYPE_DS18B20     0   // OneWire digital sensor, typ. +-0.5C accuracy
#define SENSOR_TYPE_ANALOG_LM35 1   // Analog LM35, 10mV/C, via ESP32 ADC (SRS1_001)
#define SENSOR_TYPE_ANALOG_NTC  2   // Analog NTC thermistor via ESP32 ADC (SRS1_001)

// Select the physically connected sensor here (compile-time selection).
// DS18B20 is recommended to meet the +-1C accuracy target (SRS1_005).
#define ACTIVE_SENSOR_TYPE   SENSOR_TYPE_DS18B20

// ============================================================
// Pin assignments (ESP32 DevKitC style boards)
// ============================================================
#define ONE_WIRE_BUS_GPIO     GPIO_NUM_4     // DS18B20 data pin (needs 4.7k pull-up to 3.3V)
#define ANALOG_TEMP_ADC_CHAN  ADC_CHANNEL_6  // GPIO34 - analog sensor (LM35/NTC) - SRS1_001
#define BUZZER_GPIO           GPIO_NUM_25    // Buzzer, driven via LEDC PWM
#define ACK_BUTTON_GPIO       GPIO_NUM_27    // Push button (to GND, internal pull-up) - silence buzzer

// ============================================================
// Mains power-supply detection (GPIO34 ADC input).
// Wiring assumption (documented, since exact wiring wasn't specified):
// a mains-derived 3.3V rail is fed into GPIO34 (through a divider if it
// isn't already 0-3.3V safe). While mains power is present this reads
// ~3.3V; once the device falls back to its internal battery, this net
// collapses to ~0V. See components/power_source.
// NOTE: shares GPIO34 / ADC_CHANNEL_6 with the optional analog temperature
// sensor (ANALOG_TEMP_ADC_CHAN) above - only use one of the two on GPIO34
// at a time (default ACTIVE_SENSOR_TYPE is DS18B20, so GPIO34 is free).
// ============================================================
#define POWER_SOURCE_ADC_CHAN                ADC_CHANNEL_6  // GPIO34
#define POWER_SOURCE_GPIO                    GPIO_NUM_34
#define POWER_SOURCE_MAIN_VOLTAGE_THRESHOLD  2.0f    // volts; >= this => mains power present
#define POWER_SOURCE_DEBOUNCE_WINDOW_MS       3000   // must be stable this long before switching state
#define POWER_SOURCE_SAMPLE_INTERVAL_MS        200   // how often main.c samples the power source

// ============================================================
// SRS3_004/005/006: Internal battery sensing strategy.
//
// Pick ACTIVE_BATTERY_SENSE_MODE to match your ACTUAL wiring:
//
//  - BATTERY_SENSE_MODE_DIRECT (default/recommended, most accurate):
//      A dedicated analog wire is tapped directly off the battery's + lead
//      (BEFORE any boost/buck regulator or power-path IC), through a
//      resistor divider, into BATTERY_ADC_CHAN. Gives a real 0-100% state
//      of charge. Requires ONE extra wire beyond the shared power+GND pair.
//
//  - BATTERY_SENSE_MODE_DIGITAL_STATUS:
//      No analog tap available, but the battery/boost/charger module
//      already exposes a single digital "low battery" status pin (often
//      labelled LBO/PB, or the pin driving a "LOW BATT" LED on cheap boost
//      modules). Only gives a binary low-battery flag, no percentage - but
//      needs just ONE extra digital wire, which most such modules already
//      break out on a header, so it's usually trivial to add.
//
//  - BATTERY_SENSE_MODE_RAIL_SAG (last resort - use only if you truly
//      cannot add ANY extra wire, i.e. the board only ever receives the
//      shared, already-regulated rail + GND from a switchover circuit that
//      feeds from EITHER the mains adapter OR the battery's boost
//      converter): the battery's real voltage is intentionally hidden by
//      that regulator, so an accurate percentage is NOT physically
//      possible from these 2 wires alone. This mode instead watches the
//      shared rail itself (via a divider into BATTERY_ADC_CHAN) for the
//      brief undervoltage "sag" most cheap boost converters show right
//      before they lose regulation - i.e. you get a late, coarse
//      "critical battery" warning seconds before shutdown, NOT a gradual
//      100%->0% curve. Percentage in this mode is only meaningful near 0%.
// ============================================================
#define BATTERY_SENSE_MODE_DIRECT          0
#define BATTERY_SENSE_MODE_DIGITAL_STATUS  1
#define BATTERY_SENSE_MODE_RAIL_SAG        2

#define ACTIVE_BATTERY_SENSE_MODE   BATTERY_SENSE_MODE_DIRECT

// ---- BATTERY_SENSE_MODE_DIRECT wiring ----
// The battery's + terminal is fed into GPIO35 (ADC1 channel 7) through a
// 2:1 resistor divider (e.g. two 100k resistors), so a single Li-ion
// cell's 3.0-4.2V range appears as a safe 1.5-2.1V at the ADC pin.
#define BATTERY_ADC_CHAN                 ADC_CHANNEL_7   // GPIO35
#define BATTERY_GPIO                     GPIO_NUM_35
#define BATTERY_VOLTAGE_DIVIDER_RATIO    2.0f    // ADC pin voltage x this = actual battery voltage
#define BATTERY_VOLTAGE_MAX              4.2f    // volts -> 100% (single-cell Li-ion, fully charged)
#define BATTERY_VOLTAGE_MIN              3.0f    // volts -> 0%   (single-cell Li-ion, discharge cutoff)

// ---- BATTERY_SENSE_MODE_DIGITAL_STATUS wiring ----
// Wire the module's low-battery status pin (LBO/PB/etc.) straight into a
// spare GPIO. Most of these outputs are open-drain, active-LOW when the
// battery is low, so we'd normally enable the internal pull-up - BUT
// GPIO34-39 on the original ESP32 are input-only and have NO internal
// pull-up/pull-down resistors. If you keep BATTERY_STATUS_GPIO on GPIO35,
// add an external 10k pull-up to 3.3V on that line. If you'd rather rely
// on the internal pull-up, change BATTERY_STATUS_GPIO to a normal
// bidirectional GPIO instead (e.g. GPIO26 or GPIO33, if free on your board).
#define BATTERY_STATUS_GPIO              GPIO_NUM_35     // spare digital-capable GPIO (needs external pull-up - see above)
#define BATTERY_STATUS_ACTIVE_LOW        1               // 1 = pin reads LOW when battery is low

// ---- BATTERY_SENSE_MODE_RAIL_SAG wiring ----
// Reuses BATTERY_ADC_CHAN/BATTERY_GPIO above, but the divider is sized for
// the shared rail's nominal voltage (e.g. 5V), not the raw battery. Example:
// a 100k/56k divider on a 5V rail -> ~1.8V at the ADC pin (ratio ~2.79).
#define RAIL_SAG_DIVIDER_RATIO           2.79f
#define RAIL_NOMINAL_VOLTAGE             5.0f    // volts; treated as "100%" (rail healthy)
#define RAIL_SAG_CRITICAL_VOLTAGE        4.5f    // volts; treated as "0%" (converter about to drop out)

#define BATTERY_LOW_PERCENT              20      // SRS3_005: at/below this -> low-battery alarm
#define BATTERY_CRITICAL_PERCENT          5      // SRS3_006: at/below this -> critical, snapshot + save
#define BATTERY_LOW_HYSTERESIS_CNT        5      // consecutive samples to confirm/clear low-battery
#define BATTERY_CRITICAL_HYSTERESIS_CNT   5      // consecutive samples to confirm/clear critical-battery

// DHT11 temperature/humidity sensor (optional, independent of the main
// cold-chain sensor above). Needs a 4.7k-10k pull-up to 3.3V on the data
// line (most DHT11 breakout boards already include one on-board).
// SRS2_001: humidity is read via the DHT11's proprietary single-wire
// protocol (bit-banged GPIO) - documented assumption, since the requirement
// text left the protocol TBD ("GPIO or any other protocol").
#define ENABLE_DHT11          1
#define DHT11_GPIO            GPIO_NUM_18
#define DHT11_SAMPLE_INTERVAL_MS  2000   // DHT11 max sample rate is ~1Hz

// SRS2_009: only one humidity sensor type is currently implemented (DHT11),
// but the getter function pattern mirrors SRS1_009 so more types could be
// added later the same way ACTIVE_SENSOR_TYPE works for temperature.

// ILI9341 TFT display over SPI. These pins avoid the sensor and modem pins.
#define LCD_SPI_SCLK_GPIO       GPIO_NUM_14
#define LCD_SPI_MOSI_GPIO       GPIO_NUM_13
#define LCD_SPI_MISO_GPIO       GPIO_NUM_12
#define LCD_SPI_CS_GPIO         GPIO_NUM_15
#define LCD_SPI_DC_GPIO         GPIO_NUM_2
#define LCD_SPI_RESET_GPIO      (-1)  // TFT RESET is connected to ESP32 EN
#define LCD_SPI_BACKLIGHT_GPIO  GPIO_NUM_21
#define LCD_WIDTH               240
#define LCD_HEIGHT              320

// UART for SIM800L / SIM900 GSM module
#define GSM_UART_PORT         UART_NUM_2
#define GSM_UART_TX_GPIO      GPIO_NUM_17
#define GSM_UART_RX_GPIO      GPIO_NUM_16
#define GSM_BAUD_RATE         9600
#define SMS_SEND_TIMEOUT_MS   5000

// ============================================================
// SRS1_002 / SRS1_003 / SRS1_004 / SRS1_008: default configurable properties
// Persisted at runtime in ESP32 NVS (see nvs_storage.c) and changeable via
// the serial console (see main.c "SET ..." commands).
// ============================================================
    #define DEFAULT_TEMP_HIGH_LIMIT      30.0f   // SRS1_002
#define DEFAULT_TEMP_LOW_LIMIT        0.0f   // SRS1_003
#define DEFAULT_TEMP_RESOLUTION       0.1f   // SRS1_004 (deg C per step)

// SRS1_008: temperatureHysteresis = 30
// Interpretation: number of CONSECUTIVE samples for which the temperature
// must remain beyond (or back within) a limit before the firmware accepts
// the change as real (debounce / anti-chatter filter), i.e. a "count" of
// samples, not a temperature delta. At a 1s sample rate this is a 30s
// confirmation window. (Documented assumption - spec text is ambiguous.)
#define DEFAULT_TEMP_HYSTERESIS_CNT   3

// ============================================================
// SRS2_002 / SRS2_003 / SRS2_004 / SRS2_008: humidity configurable properties
// Persisted at runtime in ESP32 NVS (see nvs_storage.c) and changeable via
// the serial console (see main.c "SET HUM..." commands).
// ============================================================
#define DEFAULT_HUMIDITY_HIGH_LIMIT   100.0f  // SRS2_002
#define DEFAULT_HUMIDITY_LOW_LIMIT      0.0f  // SRS2_003
#define DEFAULT_HUMIDITY_RESOLUTION      0.1f // SRS2_004 (%RH per step)

// SRS2_008: humidityHysteresis = 30 (consecutive-sample debounce count,
// same interpretation/assumption as SRS1_008 for temperature).
#define DEFAULT_HUMIDITY_HYSTERESIS_CNT 30

// ============================================================
// Alarm IDs
// ============================================================
#define ALARM_ID_HIGH_TEMP     1006   // SRS1_006
#define ALARM_ID_LOW_TEMP      1007   // SRS1_007
#define ALARM_ID_SENSOR_FAULT  1010   // SRS1_010
#define ALARM_ID_HIGH_HUMIDITY        2006   // SRS2_006
#define ALARM_ID_LOW_HUMIDITY         2007   // SRS2_007
#define ALARM_ID_HUMIDITY_SENSOR_FAULT 2010  // SRS2_010

// ============================================================
// Buzzer (SRS1_006 / SRS1_007: "activate buzzer at a defined frequency")
// ============================================================
#define BUZZER_LEDC_TIMER       LEDC_TIMER_0
#define BUZZER_LEDC_CHANNEL     LEDC_CHANNEL_0
#define BUZZER_LEDC_MODE        LEDC_LOW_SPEED_MODE
#define BUZZER_LEDC_DUTY_RES    LEDC_TIMER_8_BIT   // 0-255 duty range
#define BUZZER_LEDC_DUTY_ON     128                // 50% duty = audible tone

#define BUZZER_FREQ_HIGH_ALARM_HZ   2500
#define BUZZER_FREQ_LOW_ALARM_HZ    2000
#define BUZZER_FREQ_FAULT_ALARM_HZ  1500
#define BUZZER_BEEP_ON_MS            300
#define BUZZER_BEEP_OFF_MS           700

// SRS2_006 / SRS2_007: distinct tones for humidity alarms so they can be
// told apart from temperature alarms by ear.
#define BUZZER_FREQ_HIGH_HUMIDITY_ALARM_HZ   2700
#define BUZZER_FREQ_LOW_HUMIDITY_ALARM_HZ    2200
#define BUZZER_FREQ_HUMIDITY_FAULT_ALARM_HZ  1700

// Power-source alarm tone (distinct from the temperature/humidity tones).
#define BUZZER_FREQ_POWER_ALARM_HZ           1900

// SRS3_005/006: battery alarm tones (distinct from all of the above).
#define BUZZER_FREQ_LOW_BATTERY_ALARM_HZ      1600
#define BUZZER_FREQ_CRITICAL_BATTERY_ALARM_HZ 1300

// ============================================================
// SRS1_010: Sensor fault detection thresholds
// ============================================================
#define SENSOR_FAULT_CONSEC_READS     5     // consecutive bad reads -> declare fault
#define SENSOR_RECOVER_CONSEC_READS   5     // consecutive good reads -> clear fault (SRS1_011)
#define DS18B20_DISCONNECT_VALUE   -127.0f  // no presence pulse / bad CRC sentinel
#define DS18B20_POWERON_RESET_VALUE 85.0f   // DS18B20 power-on-reset garbage value
#define ANALOG_OPEN_LOW_RAW           20    // raw ADC (0-4095, 12-bit) below this => broken/open wire
#define ANALOG_OPEN_HIGH_RAW        4075    // raw ADC above this => shorted/open wire

// ============================================================
// SRS2_010: Humidity (DHT11) sensor fault detection.
// Documented assumption: a "connection problem" is detected the same way
// as the DS18B20 (SRS1_010) - i.e. the sensor fails to respond to the
// handshake, or its checksum doesn't validate (electrical noise / bad
// wiring), confirmed over several consecutive reads to avoid false
// positives from a single missed 1-second timing window.
// ============================================================
#define HUMIDITY_FAULT_CONSEC_READS    5    // consecutive bad reads -> declare fault (SRS2_010)
#define HUMIDITY_RECOVER_CONSEC_READS  5    // consecutive good reads -> clear fault (SRS2_011)

// ============================================================
// SMS destination
// ============================================================
#define SMS_DESTINATION_NUMBER  "+10000000000"   // TODO: set the real destination number

// ============================================================
// Sampling
// ============================================================
#define SENSOR_SAMPLE_INTERVAL_MS   1000
#define LCD_REFRESH_INTERVAL_MS      500
#define BUZZER_UPDATE_INTERVAL_MS     50

#endif // COLDWATCH_CONFIG_H

/*
 * dht11.c
 * Bit-banged DHT11 driver. Timings per the DHT11 datasheet:
 *
 *   1. Host pulls the line low for >= 18ms (start signal), then releases it.
 *   2. Sensor responds: pulls low ~80us, then high ~80us.
 *   3. Sensor then clocks out 40 bits (5 bytes: humidity int, humidity dec,
 *      temp int, temp dec, checksum). Each bit is a ~50us low pulse
 *      followed by a high pulse whose length encodes the bit:
 *        ~26-28us high -> '0'
 *        ~70us    high -> '1'
 *   4. checksum == sum of the first 4 bytes (truncated to 8 bits).
 *
 * Uses esp_rom_delay_us() for short busy-wait delays, same approach as
 * onewire.c.
 */
#include "dht11.h"
#include "esp_rom_sys.h" // esp_rom_delay_us

// Generous timeout for any single wait-for-edge step; if the line never
// transitions within this window we treat it as "sensor not responding".
#define DHT11_WAIT_TIMEOUT_US   200

// Threshold to distinguish a '0' bit (~26-28us high) from a '1' bit
// (~70us high). Halfway between the two is a safe cutoff.
#define DHT11_BIT_THRESHOLD_US   40

static gpio_num_t s_pin;

static inline void pin_low_output(gpio_num_t pin) {
    gpio_set_direction(pin, GPIO_MODE_OUTPUT_OD);
    gpio_set_level(pin, 0);
}

static inline void pin_release(gpio_num_t pin) {
    // Open-drain, released high via the external pull-up.
    gpio_set_direction(pin, GPIO_MODE_OUTPUT_OD);
    gpio_set_level(pin, 1);
}

// Busy-waits while the pin stays at 'level'. Returns the elapsed time in
// microseconds once the pin changes, or -1 if 'timeout_us' is exceeded.
static int wait_while_level(gpio_num_t pin, int level, int timeout_us) {
    int elapsed = 0;
    while (gpio_get_level(pin) == level) {
        if (elapsed >= timeout_us) {
            return -1;
        }
        esp_rom_delay_us(1);
        elapsed++;
    }
    return elapsed;
}

void dht11_init(gpio_num_t pin) {
    s_pin = pin;
    gpio_reset_pin(pin);
    gpio_set_pull_mode(pin, GPIO_PULLUP_ONLY);
    pin_release(pin);
}

// Runs the handshake + 40-bit read into 'data'. Returns false as soon as any
// expected edge/timing doesn't show up (timeout / disconnected sensor).
// Leaves the bus in whatever state it was in when it returned; the caller
// is responsible for releasing the bus afterwards either way.
static bool read_raw_frame(uint8_t data[5]) {
    // ---- 1. Host start signal: pull low for 20ms (>= 18ms required) ----
    pin_low_output(s_pin);
    esp_rom_delay_us(20000);

    // ---- 2. Release the bus and wait for the sensor's response ----
    pin_release(s_pin);
    esp_rom_delay_us(30);
    gpio_set_direction(s_pin, GPIO_MODE_INPUT);

    if (wait_while_level(s_pin, 1, DHT11_WAIT_TIMEOUT_US) < 0) {
        return false; // bus never went high after release
    }
    if (wait_while_level(s_pin, 0, DHT11_WAIT_TIMEOUT_US) < 0) {
        return false; // missing the ~80us "present" low pulse
    }
    if (wait_while_level(s_pin, 1, DHT11_WAIT_TIMEOUT_US) < 0) {
        return false; // missing the ~80us "present" high pulse
    }

    // ---- 3. Read 40 data bits ----
    for (int i = 0; i < 40; i++) {
        if (wait_while_level(s_pin, 0, DHT11_WAIT_TIMEOUT_US) < 0) {
            return false; // missing the ~50us low lead-in for this bit
        }
        int high_us = wait_while_level(s_pin, 1, DHT11_WAIT_TIMEOUT_US);
        if (high_us < 0) {
            return false;
        }
        data[i / 8] <<= 1;
        if (high_us > DHT11_BIT_THRESHOLD_US) {
            data[i / 8] |= 1;
        }
    }
    return true;
}

bool dht11_read(float *out_temperature_c, float *out_humidity_pct) {
    uint8_t data[5] = {0};

    bool got_frame = read_raw_frame(data);
    pin_release(s_pin); // idle the bus high again for the next read, either way

    if (!got_frame) {
        return false;
    }

    // ---- 4. Validate checksum ----
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        return false; // corrupted frame
    }

    *out_humidity_pct  = (float)data[0] + (float)data[1] / 10.0f;
    *out_temperature_c = (float)data[2] + (float)data[3] / 10.0f;
    return true;
}

/*
 * dht11.h
 * Minimal bit-banged single-wire driver for the DHT11 temperature/humidity
 * sensor, pure C (no Arduino "DHT" library). Not to be confused with the
 * Dallas/Maxim OneWire bus used by the DS18B20 — DHT11 uses its own,
 * simpler single-wire protocol with different timings.
 */
#ifndef COLDWATCH_DHT11_H
#define COLDWATCH_DHT11_H

#include <stdint.h>
#include <stdbool.h>
#include "driver/gpio.h"

// Configure the GPIO used for the DHT11 data line. The line needs an
// external ~4.7k-10k pull-up to 3.3V (most DHT11 breakout boards already
// include one).
void dht11_init(gpio_num_t pin);

// Take one reading from the sensor.
// Returns true and fills *out_temperature_c / *out_humidity_pct on success.
// Returns false on timeout / checksum failure (e.g. no response, wiring
// fault, or reading too soon after the previous sample — DHT11 needs
// >= 1s between reads).
bool dht11_read(float *out_temperature_c, float *out_humidity_pct);

#endif // COLDWATCH_DHT11_H

