static void clear_screen(void) {
    static uint16_t row[LCD_WIDTH * 20];
    memset(row, 0, sizeof(row));
    for (uint16_t y = 0; y < LCD_HEIGHT; y += 20) {
        uint16_t height = (LCD_HEIGHT - y < 20) ? LCD_HEIGHT - y : 20;
        ESP_ERROR_CHECK(esp_lcd_panel_draw_bitmap(s_panel, 0, y, LCD_WIDTH, y + height, row));
    }
}

void lcd_init(void) {
    spi_bus_config_t bus_config = {
        .sclk_io_num = LCD_SPI_SCLK_GPIO,
        .mosi_io_num = LCD_SPI_MOSI_GPIO,
        .miso_io_num = LCD_SPI_MISO_GPIO,
        .quadwp_io_num = -1,
        .quadhd_io_num = -1,
        .max_transfer_sz = LCD_WIDTH * 20 * sizeof(uint16_t),
    };
    ESP_ERROR_CHECK(spi_bus_initialize(SPI2_HOST, &bus_config, SPI_DMA_DISABLED));

    esp_lcd_panel_io_handle_t io;
    esp_lcd_panel_io_spi_config_t io_config = {
        .cs_gpio_num = LCD_SPI_CS_GPIO,
        .dc_gpio_num = LCD_SPI_DC_GPIO,
        .pclk_hz = 20 * 1000 * 1000,
        .spi_mode = 0,
        .trans_queue_depth = 1,
        .lcd_cmd_bits = 8,
        .lcd_param_bits = 8,
    };
    ESP_ERROR_CHECK(esp_lcd_new_panel_io_spi(
        (esp_lcd_spi_bus_handle_t)SPI2_HOST, &io_config, &io));

    esp_lcd_panel_dev_config_t panel_config = {
        .reset_gpio_num = LCD_SPI_RESET_GPIO,
        .rgb_ele_order = LCD_RGB_ELEMENT_ORDER_RGB,
        .bits_per_pixel = 16,
    };
    ESP_ERROR_CHECK(esp_lcd_new_panel_ili9341(io, &panel_config, &s_panel));
    ESP_ERROR_CHECK(esp_lcd_panel_reset(s_panel));
    ESP_ERROR_CHECK(esp_lcd_panel_init(s_panel));
   ESP_ERROR_CHECK(esp_lcd_panel_swap_xy(s_panel, true));
   // ESP_ERROR_CHECK(esp_lcd_panel_mirror(s_panel, false, false));   

    ESP_ERROR_CHECK(esp_lcd_panel_disp_on_off(s_panel, true));

    gpio_set_direction(LCD_SPI_BACKLIGHT_GPIO, GPIO_MODE_OUTPUT);
    gpio_set_level(LCD_SPI_BACKLIGHT_GPIO, 1);
    clear_screen();
    draw_text(12, 20, "COLDWATCH", 0xffff);
}

void lcd_show_normal(const char *sensor_type_name, float temperature, bool temp_valid,
                     const char *humidity_sensor_type_name, float humidity, bool humidity_valid,
                     const char *power_source_name, float battery_voltage, uint8_t battery_percentage,
                     bool battery_reading_is_accurate) {
    char date_line[32];
    char time_line[32];
    char temperature_line[32];
    char humidity_line[32];
    char power_line[32];
    time_t current_time = time(NULL);
    struct tm current_tm;

    localtime_r(&current_time, &current_tm);
    clear_screen();
    snprintf(date_line, sizeof(date_line), "DATE : %02d/%02d/%02d",
             current_tm.tm_mday, current_tm.tm_mon + 1, (current_tm.tm_year + 1900) % 100);
    snprintf(time_line, sizeof(time_line), "TIME : %02d:%02d:%02d",
             current_tm.tm_hour, current_tm.tm_min, current_tm.tm_sec);
    if (temp_valid) snprintf(temperature_line, sizeof(temperature_line), "TEMP : %04.1f \xb0" "C", temperature);
    else snprintf(temperature_line, sizeof(temperature_line), "TEMP : --.- \xb0" "C");
    if (humidity_valid) snprintf(humidity_line, sizeof(humidity_line), "HUM : %04.1f %%RH", humidity);
    else snprintf(humidity_line, sizeof(humidity_line), "HUM : --.- %%RH");
    // SRS3_001/003/004: power source + battery percentage/voltage.
    // battery_voltage == 0 means no analog reading exists at all (e.g.
    // BATTERY_SENSE_MODE_DIGITAL_STATUS) - show a plain OK/LOW status
    // instead of a fabricated voltage/percentage in that case.
    if (battery_voltage > 0.01f) {
        snprintf(power_line, sizeof(power_line), "PWR:%s BATT:%u%% %.1fV",
                 power_source_name ? power_source_name : "--", battery_percentage, battery_voltage);
    } else {
        snprintf(power_line, sizeof(power_line), "PWR:%s BATT:%s",
                 power_source_name ? power_source_name : "--",
                 battery_percentage >= BATTERY_LOW_PERCENT ? "OK" : "LOW");
    }
    (void)battery_reading_is_accurate; // reserved for future LCD annotation

    draw_text(12, 8, "COLD STORAGE", 0xffff);
    draw_text(12, 38, date_line, 0xffff);
    draw_text(12, 68, time_line, 0xffff);
    draw_text(12, 98, temperature_line, 0x07e0);
    draw_text(12, 128, humidity_line, 0x07ff);
    draw_text(12, 158, power_line, 0xffe0);
    draw_text(12, 188, "GSM: 4G WIFI: OK", 0xffff);
    draw_text(12, 218, "STATUS: NORMAL", 0x07e0);

    printf("LCD:\nCOLD STORAGE\n%s\n%s\n%s\n%s\n%s\nGSM: 4G WIFI: OK\nSTATUS: NORMAL\n",
           date_line, time_line, temperature_line, humidity_line, power_line);
    (void)sensor_type_name;
    (void)humidity_sensor_type_name;
}

void lcd_show_alarm(uint16_t alarm_id, const char *text) {
    char line[32];
    clear_screen();
    snprintf(line, sizeof(line), "ALARM %u", alarm_id);
    draw_text(12, 60, line, 0xf800);
    draw_text(12, 115, text, 0xf800);
}

/*
 * nvs_storage.h
 * Non-volatile storage using the ESP32's real NVS (Non-Volatile Storage) API.
 *  - Persists configurable properties (SRS1_002/003/004/008)
 *  - Maintains a circular event log for alarms (SRS1_006/007/010 "log file")
 */
#ifndef COLDWATCH_NVS_STORAGE_H
#define COLDWATCH_NVS_STORAGE_H

#include <stdint.h>
#include <stdbool.h>

// ---- Configurable properties, persisted in NVS ----
typedef struct {
    float    temperatureHighLimit;   // SRS1_002
    float    temperatureLowLimit;    // SRS1_003
    float    temperatureResolution;  // SRS1_004
    uint16_t temperatureHysteresis;  // SRS1_008 (sample count)
} coldwatch_config_t;

// ---- Log entry ----
typedef struct {
    int64_t  timestampMs;       // esp_timer_get_time()/1000 at time of event
    uint16_t alarmId;           // 1006 / 1007 / 1010
    uint8_t  eventType;         // 0 = RAISED, 1 = CLEARED
    int16_t  tempTimesHundred;  // temperature * 100 (or INT16_MIN if invalid)
} coldwatch_log_entry_t;

#define LOG_EVENT_RAISED   0
#define LOG_EVENT_CLEARED  1
#define LOG_MAX_ENTRIES    64

// Must be called once at startup (initializes nvs_flash + loads/creates config).
void nvs_storage_init(void);

// Config access (SRS1_002/003/004/008)
coldwatch_config_t *nvs_storage_get_config(void);
void nvs_storage_save_config(void);
void nvs_storage_reset_config_to_defaults(void);
void nvs_storage_set_high_limit(float v);
void nvs_storage_set_low_limit(float v);
void nvs_storage_set_resolution(float v);
void nvs_storage_set_hysteresis(uint16_t v);

// Log file (SRS1_006/007/010 event recording)
void nvs_storage_append_log(uint16_t alarmId, uint8_t eventType, float temperature);
void nvs_storage_dump_log(void); // prints via printf/ESP_LOG

#endif // COLDWATCH_NVS_STORAGE_H

/*
 * nvs_storage.h
 * Non-volatile storage using the ESP32's real NVS (Non-Volatile Storage) API.
 *  - Persists configurable properties (SRS1_002/003/004/008)
 *  - Maintains a circular event log for alarms (SRS1_006/007/010 "log file")
 */
#ifndef COLDWATCH_NVS_STORAGE_H
#define COLDWATCH_NVS_STORAGE_H

#include <stdint.h>
#include <stdbool.h>

// ---- Configurable properties, persisted in NVS ----
typedef struct {
    float    temperatureHighLimit;   // SRS1_002
    float    temperatureLowLimit;    // SRS1_003
    float    temperatureResolution;  // SRS1_004
    uint16_t temperatureHysteresis;  // SRS1_008 (sample count)
    float    humidityHighLimit;      // SRS2_002
    float    humidityLowLimit;       // SRS2_003
    float    humidityResolution;     // SRS2_004
    uint16_t humidityHysteresis;     // SRS2_008 (sample count)
} coldwatch_config_t;

// ---- Log entry ----
typedef struct {
    int64_t  timestampMs;       // esp_timer_get_time()/1000 at time of event
    uint16_t alarmId;           // 1006 / 1007 / 1010 / 2006 / 2007 / 2010
    uint8_t  eventType;         // 0 = RAISED, 1 = CLEARED
    int16_t  tempTimesHundred;  // temperature or humidity * 100 (or INT16_MIN if invalid)
} coldwatch_log_entry_t;

#define LOG_EVENT_RAISED   0
#define LOG_EVENT_CLEARED  1
#define LOG_MAX_ENTRIES    64

// ---- SRS3_006: Emergency data snapshot ----
// Saved to NVS when the battery reaches BATTERY_CRITICAL_PERCENT, so the
// last known readings survive a possible imminent power-off/brown-out.
typedef struct {
    int64_t timestampMs;
    float   temperature;
    uint8_t temperatureValid;   // 1 = 'temperature' is a real reading
    float   humidity;
    uint8_t humidityValid;      // 1 = 'humidity' is a real reading
    float   batteryVoltage;
    uint8_t batteryPercentage;
    uint8_t onBattery;          // 1 = running on internal battery at snapshot time
} coldwatch_emergency_snapshot_t;

// Must be called once at startup (initializes nvs_flash + loads/creates config).
void nvs_storage_init(void);

// Config access (SRS1_002/003/004/008)
coldwatch_config_t *nvs_storage_get_config(void);
void nvs_storage_save_config(void);
void nvs_storage_reset_config_to_defaults(void);
void nvs_storage_set_high_limit(float v);
void nvs_storage_set_low_limit(float v);
void nvs_storage_set_resolution(float v);
void nvs_storage_set_hysteresis(uint16_t v);

// Humidity config access (SRS2_002/003/004/008)
void nvs_storage_set_humidity_high_limit(float v);
void nvs_storage_set_humidity_low_limit(float v);
void nvs_storage_set_humidity_resolution(float v);
void nvs_storage_set_humidity_hysteresis(uint16_t v);

// Log file (SRS1_006/007/010, SRS2_006/007/010 event recording)
void nvs_storage_append_log(uint16_t alarmId, uint8_t eventType, float temperature);
void nvs_storage_dump_log(void); // prints via printf/ESP_LOG

// SRS3_006: emergency snapshot (persisted last-known state on critical battery)
void nvs_storage_save_emergency_snapshot(const coldwatch_emergency_snapshot_t *snap);
// Returns true if a previously-saved snapshot was found and loaded into 'out_snap'.
bool nvs_storage_load_emergency_snapshot(coldwatch_emergency_snapshot_t *out_snap);
void nvs_storage_dump_emergency_snapshot(void); // prints via printf, for the "SNAP" console command

#endif // COLDWATCH_NVS_STORAGE_H

/*
 * nvs_storage.c
 */
#include "nvs_storage.h"
#include "config.h"
#include <string.h>
#include <stdio.h>
#include "esp_log.h"
#include "esp_timer.h"
#include "nvs_flash.h"
#include "nvs.h"

static const char *TAG = "NVS_STORAGE";
#define NVS_NAMESPACE   "coldwatch"
#define KEY_CONFIG      "cfg"
#define KEY_LOG_IDX     "log_idx"

static coldwatch_config_t s_config;
static uint16_t s_log_write_index = 0;
static nvs_handle_t s_handle;

static void load_or_init_config(void) {
    size_t required_size = sizeof(coldwatch_config_t);
    esp_err_t err = nvs_get_blob(s_handle, KEY_CONFIG, &s_config, &required_size);
    if (err != ESP_OK || required_size != sizeof(coldwatch_config_t)) {
        ESP_LOGW(TAG, "Config not found / invalid (err=%s) -> loading defaults", esp_err_to_name(err));
        nvs_storage_reset_config_to_defaults();
    } else {
        ESP_LOGI(TAG, "Config loaded from NVS: high=%.1f low=%.1f res=%.2f hyst=%u",
                 s_config.temperatureHighLimit, s_config.temperatureLowLimit,
                 s_config.temperatureResolution, s_config.temperatureHysteresis);
    }
}

void nvs_storage_init(void) {
    esp_err_t err = nvs_flash_init();
    if (err == ESP_ERR_NVS_NO_FREE_PAGES || err == ESP_ERR_NVS_NEW_VERSION_FOUND) {
        // NVS partition truncated/corrupt or format changed -> erase and retry
        ESP_ERROR_CHECK(nvs_flash_erase());
        err = nvs_flash_init();
    }
    ESP_ERROR_CHECK(err);

    ESP_ERROR_CHECK(nvs_open(NVS_NAMESPACE, NVS_READWRITE, &s_handle));

    load_or_init_config();

    size_t idx_size = sizeof(s_log_write_index);
    err = nvs_get_blob(s_handle, KEY_LOG_IDX, &s_log_write_index, &idx_size);
    if (err != ESP_OK || s_log_write_index >= LOG_MAX_ENTRIES) {
        s_log_write_index = 0;
        nvs_set_blob(s_handle, KEY_LOG_IDX, &s_log_write_index, sizeof(s_log_write_index));
        nvs_commit(s_handle);
    }
}

coldwatch_config_t *nvs_storage_get_config(void) {
    return &s_config;
}

void nvs_storage_save_config(void) {
    ESP_ERROR_CHECK(nvs_set_blob(s_handle, KEY_CONFIG, &s_config, sizeof(s_config)));
    ESP_ERROR_CHECK(nvs_commit(s_handle));
}

void nvs_storage_reset_config_to_defaults(void) {
    s_config.temperatureHighLimit  = DEFAULT_TEMP_HIGH_LIMIT;    // SRS1_002
    s_config.temperatureLowLimit   = DEFAULT_TEMP_LOW_LIMIT;     // SRS1_003
    s_config.temperatureResolution = DEFAULT_TEMP_RESOLUTION;    // SRS1_004
    s_config.temperatureHysteresis = DEFAULT_TEMP_HYSTERESIS_CNT;// SRS1_008
    nvs_storage_save_config();
}

void nvs_storage_set_high_limit(float v)     { s_config.temperatureHighLimit = v; nvs_storage_save_config(); }
void nvs_storage_set_low_limit(float v)      { s_config.temperatureLowLimit = v; nvs_storage_save_config(); }
void nvs_storage_set_resolution(float v)     { s_config.temperatureResolution = v; nvs_storage_save_config(); }
void nvs_storage_set_hysteresis(uint16_t v)  { s_config.temperatureHysteresis = v; nvs_storage_save_config(); }

void nvs_storage_append_log(uint16_t alarmId, uint8_t eventType, float temperature) {
    coldwatch_log_entry_t entry;
    memset(&entry, 0, sizeof(entry));
    entry.timestampMs = esp_timer_get_time() / 1000;
    entry.alarmId = alarmId;
    entry.eventType = eventType;
    entry.tempTimesHundred = (temperature == temperature) /* not NaN */
                                 ? (int16_t)(temperature * 100.0f)
                                 : (int16_t)0x8000;

    char key[16];
    snprintf(key, sizeof(key), "log_%u", (unsigned)s_log_write_index);
    nvs_set_blob(s_handle, key, &entry, sizeof(entry));

    s_log_write_index = (s_log_write_index + 1) % LOG_MAX_ENTRIES; // circular buffer
    nvs_set_blob(s_handle, KEY_LOG_IDX, &s_log_write_index, sizeof(s_log_write_index));
    nvs_commit(s_handle);

    ESP_LOGI(TAG, "[LOG] alarm=%u event=%s temp=%.2f t=%lldms",
              alarmId, eventType == LOG_EVENT_RAISED ? "RAISED" : "CLEARED",
              temperature, entry.timestampMs);
}

void nvs_storage_dump_log(void) {
    printf("---- ColdWatch NVS Log Dump ----\n");
    for (uint16_t i = 0; i < LOG_MAX_ENTRIES; i++) {
        char key[16];
        snprintf(key, sizeof(key), "log_%u", (unsigned)i);
        coldwatch_log_entry_t entry;
        size_t sz = sizeof(entry);
        esp_err_t err = nvs_get_blob(s_handle, key, &entry, &sz);
        if (err != ESP_OK || entry.alarmId == 0) continue; // empty slot
        printf("%u: t=%lldms alarm=%u event=%s temp=%.2f\n",
               i, entry.timestampMs, entry.alarmId,
               entry.eventType == LOG_EVENT_RAISED ? "RAISED" : "CLEARED",
               entry.tempTimesHundred / 100.0f);
    }
    printf("---------------------------------\n");
}

/*
 * nvs_storage.c
 */
#include "nvs_storage.h"
#include "config.h"
#include <string.h>
#include <stdio.h>
#include "esp_log.h"
#include "esp_timer.h"
#include "nvs_flash.h"
#include "nvs.h"

static const char *TAG = "NVS_STORAGE";
#define NVS_NAMESPACE   "coldwatch"
#define KEY_CONFIG      "cfg"
#define KEY_LOG_IDX     "log_idx"
#define KEY_EMRG_SNAP   "emrg_snap"

static coldwatch_config_t s_config;
static uint16_t s_log_write_index = 0;
static nvs_handle_t s_handle;

static void load_or_init_config(void) {
    size_t required_size = sizeof(coldwatch_config_t);
    esp_err_t err = nvs_get_blob(s_handle, KEY_CONFIG, &s_config, &required_size);
    if (err != ESP_OK || required_size != sizeof(coldwatch_config_t)) {
        ESP_LOGW(TAG, "Config not found / invalid (err=%s) -> loading defaults", esp_err_to_name(err));
        nvs_storage_reset_config_to_defaults();
    } else {
        ESP_LOGI(TAG, "Config loaded from NVS: high=%.1f low=%.1f res=%.2f hyst=%u | "
                 "humHigh=%.1f humLow=%.1f humRes=%.2f humHyst=%u",
                 s_config.temperatureHighLimit, s_config.temperatureLowLimit,
                 s_config.temperatureResolution, s_config.temperatureHysteresis,
                 s_config.humidityHighLimit, s_config.humidityLowLimit,
                 s_config.humidityResolution, s_config.humidityHysteresis);
    }
}

void nvs_storage_init(void) {
    esp_err_t err = nvs_flash_init();
    if (err == ESP_ERR_NVS_NO_FREE_PAGES || err == ESP_ERR_NVS_NEW_VERSION_FOUND) {
        // NVS partition truncated/corrupt or format changed -> erase and retry
        ESP_ERROR_CHECK(nvs_flash_erase());
        err = nvs_flash_init();
    }
    ESP_ERROR_CHECK(err);

    ESP_ERROR_CHECK(nvs_open(NVS_NAMESPACE, NVS_READWRITE, &s_handle));

    load_or_init_config();

    size_t idx_size = sizeof(s_log_write_index);
    err = nvs_get_blob(s_handle, KEY_LOG_IDX, &s_log_write_index, &idx_size);
    if (err != ESP_OK || s_log_write_index >= LOG_MAX_ENTRIES) {
        s_log_write_index = 0;
        nvs_set_blob(s_handle, KEY_LOG_IDX, &s_log_write_index, sizeof(s_log_write_index));
        nvs_commit(s_handle);
    }
}

coldwatch_config_t *nvs_storage_get_config(void) {
    return &s_config;
}

void nvs_storage_save_config(void) {
    ESP_ERROR_CHECK(nvs_set_blob(s_handle, KEY_CONFIG, &s_config, sizeof(s_config)));
    ESP_ERROR_CHECK(nvs_commit(s_handle));
}

void nvs_storage_reset_config_to_defaults(void) {
    s_config.temperatureHighLimit  = DEFAULT_TEMP_HIGH_LIMIT;    // SRS1_002
    s_config.temperatureLowLimit   = DEFAULT_TEMP_LOW_LIMIT;     // SRS1_003
    s_config.temperatureResolution = DEFAULT_TEMP_RESOLUTION;    // SRS1_004
    s_config.temperatureHysteresis = DEFAULT_TEMP_HYSTERESIS_CNT;// SRS1_008
    s_config.humidityHighLimit     = DEFAULT_HUMIDITY_HIGH_LIMIT;    // SRS2_002
    s_config.humidityLowLimit      = DEFAULT_HUMIDITY_LOW_LIMIT;     // SRS2_003
    s_config.humidityResolution    = DEFAULT_HUMIDITY_RESOLUTION;    // SRS2_004
    s_config.humidityHysteresis    = DEFAULT_HUMIDITY_HYSTERESIS_CNT;// SRS2_008
    nvs_storage_save_config();
}

void nvs_storage_set_high_limit(float v)     { s_config.temperatureHighLimit = v; nvs_storage_save_config(); }
void nvs_storage_set_low_limit(float v)      { s_config.temperatureLowLimit = v; nvs_storage_save_config(); }
void nvs_storage_set_resolution(float v)     { s_config.temperatureResolution = v; nvs_storage_save_config(); }
void nvs_storage_set_hysteresis(uint16_t v)  { s_config.temperatureHysteresis = v; nvs_storage_save_config(); }

void nvs_storage_set_humidity_high_limit(float v)    { s_config.humidityHighLimit = v; nvs_storage_save_config(); }
void nvs_storage_set_humidity_low_limit(float v)     { s_config.humidityLowLimit = v; nvs_storage_save_config(); }
void nvs_storage_set_humidity_resolution(float v)    { s_config.humidityResolution = v; nvs_storage_save_config(); }
void nvs_storage_set_humidity_hysteresis(uint16_t v) { s_config.humidityHysteresis = v; nvs_storage_save_config(); }

void nvs_storage_append_log(uint16_t alarmId, uint8_t eventType, float temperature) {
    coldwatch_log_entry_t entry;
    memset(&entry, 0, sizeof(entry));
    entry.timestampMs = esp_timer_get_time() / 1000;
    entry.alarmId = alarmId;
    entry.eventType = eventType;
    entry.tempTimesHundred = (temperature == temperature) /* not NaN */
                                 ? (int16_t)(temperature * 100.0f)
                                 : (int16_t)0x8000;

    char key[16];
    snprintf(key, sizeof(key), "log_%u", (unsigned)s_log_write_index);
    nvs_set_blob(s_handle, key, &entry, sizeof(entry));

    s_log_write_index = (s_log_write_index + 1) % LOG_MAX_ENTRIES; // circular buffer
    nvs_set_blob(s_handle, KEY_LOG_IDX, &s_log_write_index, sizeof(s_log_write_index));
    nvs_commit(s_handle);

    ESP_LOGI(TAG, "[LOG] alarm=%u event=%s temp=%.2f t=%lldms",
              alarmId, eventType == LOG_EVENT_RAISED ? "RAISED" : "CLEARED",
              temperature, entry.timestampMs);
}

void nvs_storage_dump_log(void) {
    printf("---- ColdWatch NVS Log Dump ----\n");
    for (uint16_t i = 0; i < LOG_MAX_ENTRIES; i++) {
        char key[16];
        snprintf(key, sizeof(key), "log_%u", (unsigned)i);
        coldwatch_log_entry_t entry;
        size_t sz = sizeof(entry);
        esp_err_t err = nvs_get_blob(s_handle, key, &entry, &sz);
        if (err != ESP_OK || entry.alarmId == 0) continue; // empty slot
        printf("%u: t=%lldms alarm=%u event=%s temp=%.2f\n",
               i, entry.timestampMs, entry.alarmId,
               entry.eventType == LOG_EVENT_RAISED ? "RAISED" : "CLEARED",
               entry.tempTimesHundred / 100.0f);
    }
    printf("---------------------------------\n");
}

// ---- SRS3_006: Emergency data snapshot ----
void nvs_storage_save_emergency_snapshot(const coldwatch_emergency_snapshot_t *snap) {
    ESP_ERROR_CHECK(nvs_set_blob(s_handle, KEY_EMRG_SNAP, snap, sizeof(*snap)));
    ESP_ERROR_CHECK(nvs_commit(s_handle));
    ESP_LOGW(TAG, "[SNAPSHOT] Saved emergency snapshot: temp=%.1f hum=%.1f battV=%.2f batt%%=%u onBattery=%d",
             snap->temperature, snap->humidity, snap->batteryVoltage,
             snap->batteryPercentage, snap->onBattery);
}

bool nvs_storage_load_emergency_snapshot(coldwatch_emergency_snapshot_t *out_snap) {
    size_t sz = sizeof(*out_snap);
    esp_err_t err = nvs_get_blob(s_handle, KEY_EMRG_SNAP, out_snap, &sz);
    return (err == ESP_OK && sz == sizeof(*out_snap));
}

void nvs_storage_dump_emergency_snapshot(void) {
    coldwatch_emergency_snapshot_t snap;
    if (!nvs_storage_load_emergency_snapshot(&snap)) {
        printf("No emergency snapshot saved.\n");
        return;
    }
    printf("---- ColdWatch Emergency Snapshot ----\n");
    printf("t=%lldms temp=%s%.1f hum=%s%.1f battV=%.2f batt%%=%u source=%s\n",
           snap.timestampMs,
           snap.temperatureValid ? "" : "(invalid) ", snap.temperature,
           snap.humidityValid ? "" : "(invalid) ", snap.humidity,
           snap.batteryVoltage, snap.batteryPercentage,
           snap.onBattery ? "BATTERY" : "MAIN");
    printf("---------------------------------------\n");
}

/*
 * power_source.h
 * Mains power-supply presence detection (SRS3_001/003) and internal
 * battery voltage/percentage monitoring (SRS3_004/005/006).
 *
 * Requirement: detect whether the device is being fed from the mains
 * (main) power supply or has fallen back to its internal battery, and
 * track the battery's state of charge.
 *
 * Hardware assumption (documented, since the wiring wasn't specified):
 *  - A mains-derived 3.3V rail (from the charger/PSU) is connected to
 *    GPIO34 (ADC1 channel 6), optionally through a resistor divider if the
 *    rail is not already at a safe 0-3.3V level for the ESP32 ADC.
 *  - While mains power is present, GPIO34 reads ~3.3V.
 *  - When mains power is lost and the board switches to its internal
 *    battery, that rail collapses to ~0V, so GPIO34 reads ~0V.
 *  - Raw ADC counts are converted to real millivolts using ESP-IDF's ADC
 *    calibration API (line-fitting scheme on ESP32) when available, which
 *    is significantly more accurate than a plain raw/4095 linear
 *    approximation. Falls back to the linear approximation if calibration
 *    can't be created (e.g. required eFuse calibration bits aren't burnt).
 *
 * Battery sensing has THREE selectable modes (config.h ->
 * ACTIVE_BATTERY_SENSE_MODE), because how accurately you can measure the
 * battery depends entirely on what's physically wired:
 *  - BATTERY_SENSE_MODE_DIRECT (default): a dedicated wire taps the battery
 *    directly (before any boost/buck regulator), through a divider, into
 *    BATTERY_ADC_CHAN (GPIO35). Gives a real, accurate 0-100% reading.
 *  - BATTERY_SENSE_MODE_DIGITAL_STATUS: only a single digital "low battery"
 *    status pin is available from the battery/boost module (no analog
 *    tap). Gives a binary low-battery flag only (no percentage curve).
 *  - BATTERY_SENSE_MODE_RAIL_SAG: NO extra wire exists at all - the board
 *    only receives the shared, already-regulated rail (e.g. 5V) + GND,
 *    fed by EITHER the mains adapter OR the battery's boost converter.
 *    Since a regulator's whole job is to hide the battery's real voltage,
 *    an accurate percentage is NOT physically possible this way. This
 *    mode instead watches the shared rail for the undervoltage "sag" most
 *    cheap boost converters show right before losing regulation, giving a
 *    late, coarse "critical battery" warning only - NOT a real 100%->0%
 *    curve. Use power_source_battery_reading_is_accurate() to know which
 *    situation you're in at runtime (useful for LCD/log annotation).
 *
 * Debouncing:
 *  A raw ADC sample can be noisy or glitch momentarily during a real
 *  transition (e.g. relay/charger switch bounce). Instead of reacting to a
 *  single sample, this module requires the new reading to remain stable
 *  for POWER_SOURCE_DEBOUNCE_WINDOW_MS (see config.h) before the confirmed
 *  power source is updated. Call power_source_update() periodically (every
 *  POWER_SOURCE_SAMPLE_INTERVAL_MS) - it internally tracks time and only
 *  flips power_source_get_state() once the new reading has "won" for the
 *  full debounce window. The same call also refreshes the battery
 *  voltage/percentage (SRS3_004); low/critical debouncing for the battery
 *  is handled in alarm_manager (alarm_manager_update_battery()), mirroring
 *  the consecutive-sample hysteresis pattern used for temperature/humidity.
 */
#ifndef COLDWATCH_POWER_SOURCE_H
#define COLDWATCH_POWER_SOURCE_H

#include <stdint.h>
#include <stdbool.h>

typedef enum {
    POWER_SOURCE_MAIN    = 0,  // GPIO34 ~3.3V -> mains power supply in use
    POWER_SOURCE_BATTERY = 1   // GPIO34 ~0V   -> running on internal battery
} power_source_state_t;

// Configure the ADC/GPIO channels used to sense the power-supply rail
// (GPIO34) and the battery (mode-dependent - see config.h).
void power_source_init(void);

// Take one sample of BOTH the mains-sense reading (debounced) and the
// battery reading (mode-dependent). Call this periodically (e.g. every
// POWER_SOURCE_SAMPLE_INTERVAL_MS) from the main loop. Returns true the
// moment the CONFIRMED power source state changes (i.e. once per debounced
// transition), false otherwise.
bool power_source_update(void);

// Current confirmed (debounced) power source.
power_source_state_t power_source_get_state(void);

// Convenience helper: true while running on mains power.
bool power_source_is_main(void);

// Convenience helper: true while running on the internal battery.
bool power_source_is_battery(void);

// Last raw voltage measured on GPIO34 (volts), for diagnostics/logging.
float power_source_get_last_voltage(void);

// "MAIN" or "BATTERY", for logging / LCD display.
const char *power_source_get_state_name(void);

// ---- Battery voltage/percentage (SRS3_004) ----

// Last measured battery (or, in RAIL_SAG mode, shared-rail) voltage in
// volts. In BATTERY_SENSE_MODE_DIGITAL_STATUS this is always 0.0 (no
// analog reading exists in that mode).
float power_source_get_battery_voltage(void);

// Battery state of charge, 0-100%. Meaning depends on
// ACTIVE_BATTERY_SENSE_MODE - see power_source_battery_reading_is_accurate().
uint8_t power_source_get_battery_percentage(void);

// True if power_source_get_battery_percentage() is a real, accurate state
// of charge (BATTERY_SENSE_MODE_DIRECT). False means the value is only a
// coarse proxy (RAIL_SAG: meaningful near 0% only) or a fixed placeholder
// derived from a binary status flag (DIGITAL_STATUS) - use this to decide
// whether to show "~87%" vs. just "OK"/"LOW" on the LCD, for example.
bool power_source_battery_reading_is_accurate(void);

#endif // COLDWATCH_POWER_SOURCE_H

/*
 * power_source.c
 */
#include "power_source.h"
#include "config.h"
#include "esp_adc/adc_oneshot.h"
#include "esp_adc/adc_cali.h"
#include "esp_adc/adc_cali_scheme.h"
#include "esp_timer.h"
#include "esp_check.h"
#include "esp_log.h"
#include "driver/gpio.h"

static const char *TAG = "POWER_SOURCE";

static adc_oneshot_unit_handle_t s_adc_handle;

// ADC calibration handle, shared by both channels (GPIO34 mains-sense and
// GPIO35 battery-sense, when the latter is used in ADC mode): line-fitting
// calibration on ESP32 only depends on {unit, atten, bitwidth} - not on the
// channel - so one handle covers both. Converts raw ADC counts to real
// millivolts, correcting for the chip's inherent ADC non-linearity (a
// plain raw*3.9/4095 approximation can be off by several hundred mV).
static adc_cali_handle_t s_cali_handle = NULL;
static bool s_cali_available = false;

// Conservative default until the first sample arrives: assume battery so
// any code that reads the state before power_source_update() has run at
// least once doesn't wrongly assume mains power is present.
static power_source_state_t s_confirmed_state = POWER_SOURCE_BATTERY;
static power_source_state_t s_candidate_state  = POWER_SOURCE_BATTERY;
static int64_t s_candidate_since_ms = 0;
static float   s_last_voltage = 0.0f;
static bool    s_first_sample = true;

// Battery voltage/percentage (SRS3_004) - meaning depends on
// ACTIVE_BATTERY_SENSE_MODE, see power_source.h for the full explanation.
static float   s_battery_voltage = 0.0f;
static uint8_t s_battery_percentage = 0;

static inline int64_t millis64(void) {
    return esp_timer_get_time() / 1000;
}

static void init_calibration(void) {
    adc_cali_line_fitting_config_t cali_config = {
        .unit_id  = ADC_UNIT_1,
        .atten    = ADC_ATTEN_DB_11,
        .bitwidth = ADC_BITWIDTH_DEFAULT,
#if CONFIG_IDF_TARGET_ESP32
        .default_vref = 1100, // mV; used only if eFuse Vref/TP calibration bits aren't burnt
#endif
    };
    esp_err_t err = adc_cali_create_scheme_line_fitting(&cali_config, &s_cali_handle);
    if (err == ESP_OK) {
        s_cali_available = true;
        ESP_LOGI(TAG, "ADC line-fitting calibration active (accurate mV readings)");
    } else {
        s_cali_available = false;
        ESP_LOGW(TAG, "ADC calibration unavailable (err=%s) - falling back to "
                      "uncalibrated linear approximation for voltage readings", esp_err_to_name(err));
    }
}

void power_source_init(void) {
    const adc_oneshot_unit_init_cfg_t unit_config = {
        .unit_id  = ADC_UNIT_1,
        .ulp_mode = ADC_ULP_MODE_DISABLE,
    };
    const adc_oneshot_chan_cfg_t channel_config = {
        .atten    = ADC_ATTEN_DB_11,   // ~0-3.9V full-scale, covers a 3.3V rail
        .bitwidth = ADC_BITWIDTH_DEFAULT,
    };
    ESP_ERROR_CHECK(adc_oneshot_new_unit(&unit_config, &s_adc_handle));
    ESP_ERROR_CHECK(adc_oneshot_config_channel(s_adc_handle, POWER_SOURCE_ADC_CHAN, &channel_config));

#if ACTIVE_BATTERY_SENSE_MODE == BATTERY_SENSE_MODE_DIRECT || \
    ACTIVE_BATTERY_SENSE_MODE == BATTERY_SENSE_MODE_RAIL_SAG
    // Both modes read an analog voltage on BATTERY_ADC_CHAN (GPIO35),
    // sharing ADC1 with the mains-sense channel above (one oneshot handle
    // per physical ADC unit).
    ESP_ERROR_CHECK(adc_oneshot_config_channel(s_adc_handle, BATTERY_ADC_CHAN, &channel_config));
#elif ACTIVE_BATTERY_SENSE_MODE == BATTERY_SENSE_MODE_DIGITAL_STATUS
    // No analog battery tap available - just a single digital "low
    // battery" status pin from the battery/boost module.
    gpio_reset_pin(BATTERY_STATUS_GPIO);
    gpio_set_direction(BATTERY_STATUS_GPIO, GPIO_MODE_INPUT);
#if BATTERY_STATUS_ACTIVE_LOW
    gpio_set_pull_mode(BATTERY_STATUS_GPIO, GPIO_PULLUP_ONLY);
#else
    gpio_set_pull_mode(BATTERY_STATUS_GPIO, GPIO_PULLDOWN_ONLY);
#endif
#endif

    init_calibration();
}

// Returns the measured voltage on the given channel (volts), or a negative
// value on ADC read failure. Uses calibrated mV conversion when available
// (much more accurate than a plain raw/4095 linear approximation), and
// falls back to the linear approximation if calibration couldn't be set up.
static float read_channel_voltage(adc_channel_t chan) {
    int raw = 0;
    if (adc_oneshot_read(s_adc_handle, chan, &raw) != ESP_OK) {
        return -1.0f;
    }

    if (s_cali_available) {
        int mv = 0;
        if (adc_cali_raw_to_voltage(s_cali_handle, raw, &mv) == ESP_OK) {
            return mv / 1000.0f;
        }
    }

    // Fallback: 12-bit ADC (0-4095), ~3.9V full-scale at ADC_ATTEN_DB_11.
    return (raw * 3.9f) / 4095.0f;
}

// Linear map 'voltage' between [v0%, v100%] volts -> [0, 100] percent,
// clamped. Used for both the accurate DIRECT-mode battery curve and the
// coarse RAIL_SAG-mode proxy (with different min/max meanings - see
// config.h / power_source.h).
static uint8_t voltage_to_percentage(float voltage, float v0_percent, float v100_percent) {
    if (voltage <= v0_percent) return 0;
    if (voltage >= v100_percent) return 100;
    float pct = (voltage - v0_percent) / (v100_percent - v0_percent) * 100.0f;
    return (uint8_t)(pct + 0.5f);
}

static void update_battery_reading(void) {
#if ACTIVE_BATTERY_SENSE_MODE == BATTERY_SENSE_MODE_DIRECT
    // Accurate: dedicated wire tapped straight off the battery.
    float adc_voltage = read_channel_voltage(BATTERY_ADC_CHAN);
    if (adc_voltage < 0.0f) {
        return; // transient ADC read failure - keep last known reading
    }
    s_battery_voltage = adc_voltage * BATTERY_VOLTAGE_DIVIDER_RATIO;
    s_battery_percentage = voltage_to_percentage(s_battery_voltage, BATTERY_VOLTAGE_MIN, BATTERY_VOLTAGE_MAX);

#elif ACTIVE_BATTERY_SENSE_MODE == BATTERY_SENSE_MODE_RAIL_SAG
    // Coarse: no dedicated wire exists, so we watch the SHARED regulated
    // rail (fed by either mains or the battery's boost converter) for the
    // undervoltage sag that happens right before it loses regulation.
    // Only meaningful near 0% - see power_source.h for caveats.
    float adc_voltage = read_channel_voltage(BATTERY_ADC_CHAN);
    if (adc_voltage < 0.0f) {
        return;
    }
    s_battery_voltage = adc_voltage * RAIL_SAG_DIVIDER_RATIO;
    s_battery_percentage = voltage_to_percentage(s_battery_voltage, RAIL_SAG_CRITICAL_VOLTAGE, RAIL_NOMINAL_VOLTAGE);

#elif ACTIVE_BATTERY_SENSE_MODE == BATTERY_SENSE_MODE_DIGITAL_STATUS
    // No analog reading at all - just a binary low-battery status pin.
    // Map it onto the same 0-100 alarm-threshold scale that alarm_manager
    // already understands, without pretending to know the real percentage:
    //   status OK   -> 100% (comfortably above BATTERY_LOW_PERCENT)
    //   status LOW  -> BATTERY_LOW_PERCENT (exactly triggers the low-battery
    //                  alarm; this mode cannot distinguish low from critical)
    int level = gpio_get_level(BATTERY_STATUS_GPIO);
    bool is_low = BATTERY_STATUS_ACTIVE_LOW ? (level == 0) : (level != 0);
    s_battery_voltage = 0.0f; // no analog reading available in this mode
    s_battery_percentage = is_low ? BATTERY_LOW_PERCENT : 100;
#endif
}

bool power_source_battery_reading_is_accurate(void) {
    return ACTIVE_BATTERY_SENSE_MODE == BATTERY_SENSE_MODE_DIRECT;
}

bool power_source_update(void) {
    update_battery_reading(); // SRS3_004

    float voltage = read_channel_voltage(POWER_SOURCE_ADC_CHAN);
    if (voltage < 0.0f) {
        return false; // transient ADC read failure - keep previous confirmed state, try again next cycle
    }
    s_last_voltage = voltage;

    power_source_state_t instantaneous =
        (voltage >= POWER_SOURCE_MAIN_VOLTAGE_THRESHOLD) ? POWER_SOURCE_MAIN : POWER_SOURCE_BATTERY;

    int64_t now = millis64();

    if (s_first_sample) {
        // Seed the filter with the real, current reading on boot so we
        // report the correct initial power source immediately instead of
        // defaulting to "battery" for a whole debounce window.
        s_candidate_state    = instantaneous;
        s_candidate_since_ms = now;
        s_confirmed_state    = instantaneous;
        s_first_sample       = false;
        return false;
    }

    if (instantaneous != s_candidate_state) {
        // The reading changed -> restart the debounce timer for the new candidate.
        s_candidate_state    = instantaneous;
        s_candidate_since_ms = now;
        return false;
    }

    // The candidate reading has been stable; accept it as the confirmed
    // state only once it has held for the full debounce window.
    if (s_candidate_state != s_confirmed_state &&
        (now - s_candidate_since_ms) >= POWER_SOURCE_DEBOUNCE_WINDOW_MS) {
        s_confirmed_state = s_candidate_state;
        return true; // confirmed power source changed
    }

    return false;
}

power_source_state_t power_source_get_state(void) {
    return s_confirmed_state;
}

bool power_source_is_main(void) {
    return s_confirmed_state == POWER_SOURCE_MAIN;
}

bool power_source_is_battery(void) {
    return s_confirmed_state == POWER_SOURCE_BATTERY;
}

float power_source_get_last_voltage(void) {
    return s_last_voltage;
}

const char *power_source_get_state_name(void) {
    return (s_confirmed_state == POWER_SOURCE_MAIN) ? "MAIN" : "BATTERY";
}

float power_source_get_battery_voltage(void) {
    return s_battery_voltage;
}

uint8_t power_source_get_battery_percentage(void) {
    return s_battery_percentage;
}

/*
 * main.c
 * ColdWatch firmware entry point for ESP32 (ESP-IDF, pure C).
 *
 * Requirement coverage:
 *  SRS1_001 - temperature_sensor reads via bit-banged OneWire (DS18B20)
 *             or ESP32 ADC (LM35/NTC)
 *  SRS1_002 - config.temperatureHighLimit (NVS, default 50.0)
 *  SRS1_003 - config.temperatureLowLimit  (NVS, default 0.0)
 *  SRS1_004 - config.temperatureResolution (NVS, default 0.1)
 *  SRS1_005 - DS18B20 12-bit + resolution rounding -> +-1C target accuracy
 *  SRS1_006 - Alarm 1006 (high temp): LCD + SMS + NVS log + buzzer
 *  SRS1_007 - Alarm 1007 (low temp):  LCD + SMS + NVS log + buzzer
 *  SRS1_008 - config.temperatureHysteresis (consecutive-sample debounce)
 *  SRS1_009 - LCD shows active sensor type name
 *  SRS1_010 - Alarm 1010 (sensor fault): LCD + SMS + NVS log + buzzer
 *  SRS1_011 - Alarms 1007 & 1010 auto-clear when condition resolves
 *
 *  SRS2_001 - humidity_sensor reads via the DHT11's bit-banged single-wire
 *             protocol (see components/dht11 + components/humidity_sensor)
 *  SRS2_002 - config.humidityHighLimit (NVS, default 100.0)
 *  SRS2_003 - config.humidityLowLimit  (NVS, default 0.0)
 *  SRS2_004 - config.humidityResolution (NVS, default 0.1)
 *  SRS2_005 - target +-3RH accuracy (see README for DHT11 accuracy caveat)
 *  SRS2_006 - Alarm 2006 (high humidity): LCD + SMS + NVS log + buzzer
 *  SRS2_007 - Alarm 2007 (low humidity):  LCD + SMS + NVS log + buzzer
 *  SRS2_008 - config.humidityHysteresis (consecutive-sample debounce)
 *  SRS2_009 - LCD shows active humidity sensor type name (DHT11)
 *  SRS2_010 - Alarm 2010 (humidity sensor fault): LCD + SMS + NVS log + buzzer
 *  SRS2_011 - Alarms 2006/2007/2010 auto-clear when condition resolves
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_timer.h"
#include "esp_log.h"
#include "driver/gpio.h"
#include "driver/uart.h"

#include "config.h"
#include "nvs_storage.h"
#include "temperature_sensor.h"
#include "humidity_sensor.h"
#include "alarm_manager.h"
#include "buzzer.h"
#include "lcd_i2c.h"
#include "sms_module.h"

static const char *TAG = "ColdWatch";

static float lastTemperature = NAN;
static bool  lastTempValid = false;
static float lastHumidity = NAN;
static bool  lastHumidityValid = false;

static inline int64_t millis64(void) {
    return esp_timer_get_time() / 1000;
}

// ---------------- Serial command console (Serial Monitor / stdin over UART0) ----------------
// (SRS1_002/003/004/008, SRS2_002/003/004/008 - runtime configuration)
// Commands (newline terminated), e.g.:
//   SET HIGH 55.0
//   SET LOW -5.0
//   SET RES 0.5
//   SET HYST 20
//   SET HUMHIGH 80.0
//   SET HUMLOW 10.0
//   SET HUMRES 0.5
//   SET HUMHYST 20
//   GET
//   LOG
//   RESET
static void process_console_command(const char *line) {
    coldwatch_config_t *cfg = nvs_storage_get_config();

    if (strncmp(line, "SET HIGH ", 9) == 0) {
        nvs_storage_set_high_limit(atof(line + 9));
        printf("OK: temperatureHighLimit updated\n");
    } else if (strncmp(line, "SET LOW ", 8) == 0) {
        nvs_storage_set_low_limit(atof(line + 8));
        printf("OK: temperatureLowLimit updated\n");
    } else if (strncmp(line, "SET RES ", 8) == 0) {
        nvs_storage_set_resolution(atof(line + 8));
        printf("OK: temperatureResolution updated\n");
    } else if (strncmp(line, "SET HYST ", 9) == 0) {
        nvs_storage_set_hysteresis((uint16_t)atoi(line + 9));
        printf("OK: temperatureHysteresis updated\n");
    } else if (strncmp(line, "SET HUMHIGH ", 12) == 0) {
        nvs_storage_set_humidity_high_limit(atof(line + 12));
        printf("OK: humidityHighLimit updated\n");
    } else if (strncmp(line, "SET HUMLOW ", 11) == 0) {
        nvs_storage_set_humidity_low_limit(atof(line + 11));
        printf("OK: humidityLowLimit updated\n");
    } else if (strncmp(line, "SET HUMRES ", 11) == 0) {
        nvs_storage_set_humidity_resolution(atof(line + 11));
        printf("OK: humidityResolution updated\n");
    } else if (strncmp(line, "SET HUMHYST ", 12) == 0) {
        nvs_storage_set_humidity_hysteresis((uint16_t)atoi(line + 12));
        printf("OK: humidityHysteresis updated\n");
    } else if (strcmp(line, "GET") == 0) {
        printf("High=%.2f Low=%.2f Res=%.2f Hyst=%u | "
               "HumHigh=%.2f HumLow=%.2f HumRes=%.2f HumHyst=%u\n",
               cfg->temperatureHighLimit, cfg->temperatureLowLimit,
               cfg->temperatureResolution, cfg->temperatureHysteresis,
               cfg->humidityHighLimit, cfg->humidityLowLimit,
               cfg->humidityResolution, cfg->humidityHysteresis);
    } else if (strcmp(line, "LOG") == 0) {
        nvs_storage_dump_log();
    } else if (strcmp(line, "RESET") == 0) {
        nvs_storage_reset_config_to_defaults();
        printf("OK: config reset to defaults\n");
    } else if (strlen(line) > 0) {
        printf("ERR: unknown command\n");
    }
}

static void console_task(void *arg) {
    char buffer[64];
    size_t idx = 0;

    while (1) {
        uint8_t c;
        int len = uart_read_bytes(UART_NUM_0, &c, 1, pdMS_TO_TICKS(50));
        if (len > 0) {
            if (c == '\n' || c == '\r') {
                buffer[idx] = '\0';
                if (idx > 0) process_console_command(buffer);
                idx = 0;
            } else if (idx < sizeof(buffer) - 1) {
                buffer[idx++] = (char)c;
            }
        }
    }
}

// ---------------- Manual acknowledge / silence button ----------------
static void handle_ack_button(void) {
    static int last_state = 1; // HIGH (idle, pull-up)
    int state = gpio_get_level(ACK_BUTTON_GPIO);
    if (last_state == 1 && state == 0) {
        // Button pressed: silence buzzer immediately (does not clear the
        // underlying alarm condition/state, only stops the audible tone).
        buzzer_stop();
        ESP_LOGI(TAG, "[ACK] Buzzer silenced by user");
    }
    last_state = state;
}

// ---------------- Main application task ----------------
static void coldwatch_task(void *arg) {
    int64_t last_lcd_refresh_ms = 0;
    int64_t last_humidity_sample_ms = 0;

    while (1) {
        int64_t now = millis64();

        // ---- Sample the humidity sensor at fixed interval (SRS2_001) ----
        if (now - last_humidity_sample_ms >= DHT11_SAMPLE_INTERVAL_MS) {
            last_humidity_sample_ms = now;

            float raw_humidity_temperature;
            float raw_humidity;
            bool hum_ok = humidity_sensor_sample(&raw_humidity_temperature, &raw_humidity);
            bool hum_faulted = (humidity_sensor_get_fault_state() == HUMIDITY_SENSOR_STATE_FAULT);

            if (hum_ok) {
                coldwatch_config_t *cfg = nvs_storage_get_config();
                // DHT11 provides both values, so use it as the connected
                // temperature and humidity source.
                lastTemperature = temperature_round_to_resolution(
                    raw_humidity_temperature, cfg->temperatureResolution);
                lastTempValid = true;
                lastHumidity = humidity_round_to_resolution(raw_humidity, cfg->humidityResolution);
                lastHumidityValid = true;
                ESP_LOGI(TAG, "DHT11 temperature: %.1f C, humidity: %.1f %%RH",
                         lastTemperature, lastHumidity);
            } else {
                lastTempValid = false;
                lastHumidityValid = false;
                ESP_LOGW(TAG, "Humidity read failed (fault state: %s)",
                         hum_faulted ? "FAULT" : "DEBOUNCING");
            }

            // Evaluate both alarms from the same DHT11 sample.
            alarm_manager_update(lastTemperature, lastTempValid, false);
            alarm_manager_update_humidity(lastHumidity, lastHumidityValid, hum_faulted);
        }

        handle_ack_button();

        // ---- Refresh LCD / buzzer pattern ----
        if (now - last_lcd_refresh_ms >= LCD_REFRESH_INTERVAL_MS) {
            last_lcd_refresh_ms = now;
            // SRS1_009 / SRS2_009
            alarm_manager_refresh_outputs(humidity_sensor_get_type_name(), lastTemperature, lastTempValid,
                                           humidity_sensor_get_type_name(), lastHumidity, lastHumidityValid);
        } else {
            buzzer_update(); // keep buzzer pattern responsive between LCD refreshes
        }

        vTaskDelay(pdMS_TO_TICKS(BUZZER_UPDATE_INTERVAL_MS));
    }
}

void app_main(void) {
    ESP_LOGI(TAG, "=== ColdWatch Firmware Boot (ESP32) ===");

    // Configure UART0 for the console command interface (Serial Monitor)
    uart_driver_install(UART_NUM_0, 256 * 2, 0, 0, NULL, 0);

    gpio_reset_pin(ACK_BUTTON_GPIO);
    gpio_set_direction(ACK_BUTTON_GPIO, GPIO_MODE_INPUT);
    gpio_set_pull_mode(ACK_BUTTON_GPIO, GPIO_PULLUP_ONLY);

    nvs_storage_init();          // SRS1_002/003/004/008, SRS2_002/003/004/008 (NVS config load)
    temperature_sensor_init();   // SRS1_001
    humidity_sensor_init();      // SRS2_001
    buzzer_init();
    lcd_init();
    sms_module_init();
    alarm_manager_init();

    printf("Type GET / LOG / RESET / SET HIGH x / SET LOW x / SET RES x / SET HYST x /\n"
           "     SET HUMHIGH x / SET HUMLOW x / SET HUMRES x / SET HUMHYST x\n");

    xTaskCreate(console_task, "console_task", 4096, NULL, 5, NULL);
    xTaskCreate(coldwatch_task, "coldwatch_task", 4096, NULL, 5, NULL);
}

/*
 * main.c
 * ColdWatch firmware entry point for ESP32 (ESP-IDF, pure C).
 *
 * Requirement coverage:
 *  SRS1_001 - temperature_sensor reads via bit-banged OneWire (DS18B20)
 *             or ESP32 ADC (LM35/NTC)
 *  SRS1_002 - config.temperatureHighLimit (NVS, default 50.0)
 *  SRS1_003 - config.temperatureLowLimit  (NVS, default 0.0)
 *  SRS1_004 - config.temperatureResolution (NVS, default 0.1)
 *  SRS1_005 - DS18B20 12-bit + resolution rounding -> +-1C target accuracy
 *  SRS1_006 - Alarm 1006 (high temp): LCD + SMS + NVS log + buzzer
 *  SRS1_007 - Alarm 1007 (low temp):  LCD + SMS + NVS log + buzzer
 *  SRS1_008 - config.temperatureHysteresis (consecutive-sample debounce)
 *  SRS1_009 - LCD shows active sensor type name
 *  SRS1_010 - Alarm 1010 (sensor fault): LCD + SMS + NVS log + buzzer
 *  SRS1_011 - Alarms 1007 & 1010 auto-clear when condition resolves
 *
 *  SRS2_001 - humidity_sensor reads via the DHT11's bit-banged single-wire
 *             protocol (see components/dht11 + components/humidity_sensor)
 *  SRS2_002 - config.humidityHighLimit (NVS, default 100.0)
 *  SRS2_003 - config.humidityLowLimit  (NVS, default 0.0)
 *  SRS2_004 - config.humidityResolution (NVS, default 0.1)
 *  SRS2_005 - target +-3RH accuracy (see README for DHT11 accuracy caveat)
 *  SRS2_006 - Alarm 2006 (high humidity): LCD + SMS + NVS log + buzzer
 *  SRS2_007 - Alarm 2007 (low humidity):  LCD + SMS + NVS log + buzzer
 *  SRS2_008 - config.humidityHysteresis (consecutive-sample debounce)
 *  SRS2_009 - LCD shows active humidity sensor type name (DHT11)
 *  SRS2_010 - Alarm 2010 (humidity sensor fault): LCD + SMS + NVS log + buzzer
 *  SRS2_011 - Alarms 2006/2007/2010 auto-clear when condition resolves
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_timer.h"
#include "esp_log.h"
#include "driver/gpio.h"
#include "driver/uart.h"

#include "config.h"
#include "nvs_storage.h"
#include "temperature_sensor.h"
#include "humidity_sensor.h"
#include "alarm_manager.h"
#include "buzzer.h"
#include "lcd_i2c.h"
#include "sms_module.h"
#include "power_source.h"

static const char *TAG = "ColdWatch";

static float lastTemperature = NAN;
static bool  lastTempValid = false;
static float lastHumidity = NAN;
static bool  lastHumidityValid = false;

static inline int64_t millis64(void) {
    return esp_timer_get_time() / 1000;
}

// ---------------- Serial command console (Serial Monitor / stdin over UART0) ----------------
// (SRS1_002/003/004/008, SRS2_002/003/004/008 - runtime configuration)
// Commands (newline terminated), e.g.:
//   SET HIGH 55.0
//   SET LOW -5.0
//   SET RES 0.5
//   SET HYST 20
//   SET HUMHIGH 80.0
//   SET HUMLOW 10.0
//   SET HUMRES 0.5
//   SET HUMHYST 20
//   GET
//   LOG
//   RESET
static void process_console_command(const char *line) {
    coldwatch_config_t *cfg = nvs_storage_get_config();

    if (strncmp(line, "SET HIGH ", 9) == 0) {
        nvs_storage_set_high_limit(atof(line + 9));
        printf("OK: temperatureHighLimit updated\n");
    } else if (strncmp(line, "SET LOW ", 8) == 0) {
        nvs_storage_set_low_limit(atof(line + 8));
        printf("OK: temperatureLowLimit updated\n");
    } else if (strncmp(line, "SET RES ", 8) == 0) {
        nvs_storage_set_resolution(atof(line + 8));
        printf("OK: temperatureResolution updated\n");
    } else if (strncmp(line, "SET HYST ", 9) == 0) {
        nvs_storage_set_hysteresis((uint16_t)atoi(line + 9));
        printf("OK: temperatureHysteresis updated\n");
    } else if (strncmp(line, "SET HUMHIGH ", 12) == 0) {
        nvs_storage_set_humidity_high_limit(atof(line + 12));
        printf("OK: humidityHighLimit updated\n");
    } else if (strncmp(line, "SET HUMLOW ", 11) == 0) {
        nvs_storage_set_humidity_low_limit(atof(line + 11));
        printf("OK: humidityLowLimit updated\n");
    } else if (strncmp(line, "SET HUMRES ", 11) == 0) {
        nvs_storage_set_humidity_resolution(atof(line + 11));
        printf("OK: humidityResolution updated\n");
    } else if (strncmp(line, "SET HUMHYST ", 12) == 0) {
        nvs_storage_set_humidity_hysteresis((uint16_t)atoi(line + 12));
        printf("OK: humidityHysteresis updated\n");
    } else if (strcmp(line, "GET") == 0) {
        printf("High=%.2f Low=%.2f Res=%.2f Hyst=%u | "
               "HumHigh=%.2f HumLow=%.2f HumRes=%.2f HumHyst=%u\n",
               cfg->temperatureHighLimit, cfg->temperatureLowLimit,
               cfg->temperatureResolution, cfg->temperatureHysteresis,
               cfg->humidityHighLimit, cfg->humidityLowLimit,
               cfg->humidityResolution, cfg->humidityHysteresis);
    } else if (strcmp(line, "LOG") == 0) {
        nvs_storage_dump_log();
    } else if (strcmp(line, "POWER") == 0) {
        printf("Power source: %s (last sensed voltage: %.2fV on GPIO%u) | "
               "Battery: %u%% (%.2fV on GPIO%u) [%s]\n",
               power_source_get_state_name(), power_source_get_last_voltage(),
               (unsigned)POWER_SOURCE_GPIO,
               power_source_get_battery_percentage(), power_source_get_battery_voltage(),
               (unsigned)BATTERY_GPIO,
               power_source_battery_reading_is_accurate() ? "ACCURATE" : "ESTIMATE/STATUS-ONLY");
    } else if (strcmp(line, "SNAP") == 0) {
        nvs_storage_dump_emergency_snapshot();
    } else if (strcmp(line, "RESET") == 0) {
        nvs_storage_reset_config_to_defaults();
        printf("OK: config reset to defaults\n");
    } else if (strlen(line) > 0) {
        printf("ERR: unknown command\n");
    }
}

static void console_task(void *arg) {
    char buffer[64];
    size_t idx = 0;

    while (1) {
        uint8_t c;
        int len = uart_read_bytes(UART_NUM_0, &c, 1, pdMS_TO_TICKS(50));
        if (len > 0) {
            if (c == '\n' || c == '\r') {
                buffer[idx] = '\0';
                if (idx > 0) process_console_command(buffer);
                idx = 0;
            } else if (idx < sizeof(buffer) - 1) {
                buffer[idx++] = (char)c;
            }
        }
    }
}

// ---------------- Manual acknowledge / silence button ----------------
static void handle_ack_button(void) {
    static int last_state = 1; // HIGH (idle, pull-up)
    int state = gpio_get_level(ACK_BUTTON_GPIO);
    if (last_state == 1 && state == 0) {
        // Button pressed: silence buzzer immediately (does not clear the
        // underlying alarm condition/state, only stops the audible tone).
        buzzer_stop();
        ESP_LOGI(TAG, "[ACK] Buzzer silenced by user");
    }
    last_state = state;
}

// ---------------- Main application task ----------------
static void coldwatch_task(void *arg) {
    int64_t last_lcd_refresh_ms = 0;
    int64_t last_humidity_sample_ms = 0;
    int64_t last_power_sample_ms = 0;

    while (1) {
        int64_t now = millis64();

        // ---- Sample the main power-supply detector (GPIO34) ----
        // ~3.3V => mains power present, ~0V => running on internal battery.
        // power_source_update() applies its own debounce window internally
        // (POWER_SOURCE_DEBOUNCE_WINDOW_MS).
        if (now - last_power_sample_ms >= POWER_SOURCE_SAMPLE_INTERVAL_MS) {
            last_power_sample_ms = now;
            power_source_update();
            alarm_manager_update_power(power_source_is_battery());
            // SRS3_004/005/006: battery voltage/percentage monitoring
            alarm_manager_update_battery(power_source_get_battery_voltage(),
                                          power_source_get_battery_percentage(),
                                          power_source_is_battery(),
                                          lastTemperature, lastTempValid,
                                          lastHumidity, lastHumidityValid);
        }

        // ---- Sample the humidity sensor at fixed interval (SRS2_001) ----
        if (now - last_humidity_sample_ms >= DHT11_SAMPLE_INTERVAL_MS) {
            last_humidity_sample_ms = now;

            float raw_humidity_temperature;
            float raw_humidity;
            bool hum_ok = humidity_sensor_sample(&raw_humidity_temperature, &raw_humidity);
            bool hum_faulted = (humidity_sensor_get_fault_state() == HUMIDITY_SENSOR_STATE_FAULT);

            if (hum_ok) {
                coldwatch_config_t *cfg = nvs_storage_get_config();
                // DHT11 provides both values, so use it as the connected
                // temperature and humidity source.
                lastTemperature = temperature_round_to_resolution(
                    raw_humidity_temperature, cfg->temperatureResolution);
                lastTempValid = true;
                lastHumidity = humidity_round_to_resolution(raw_humidity, cfg->humidityResolution);
                lastHumidityValid = true;
                ESP_LOGI(TAG, "DHT11 temperature: %.1f C, humidity: %.1f %%RH",
                         lastTemperature, lastHumidity);
            } else {
                lastTempValid = false;
                lastHumidityValid = false;
                ESP_LOGW(TAG, "Humidity read failed (fault state: %s)",
                         hum_faulted ? "FAULT" : "DEBOUNCING");
            }

            // Evaluate both alarms from the same DHT11 sample.
            alarm_manager_update(lastTemperature, lastTempValid, false);
            alarm_manager_update_humidity(lastHumidity, lastHumidityValid, hum_faulted);
        }

        handle_ack_button();

        // ---- Refresh LCD / buzzer pattern ----
        if (now - last_lcd_refresh_ms >= LCD_REFRESH_INTERVAL_MS) {
            last_lcd_refresh_ms = now;
            // SRS1_009 / SRS2_009 / SRS3_001/003/004
            alarm_manager_refresh_outputs(humidity_sensor_get_type_name(), lastTemperature, lastTempValid,
                                           humidity_sensor_get_type_name(), lastHumidity, lastHumidityValid,
                                           power_source_get_state_name(),
                                           power_source_get_battery_voltage(),
                                           power_source_get_battery_percentage(),
                                           power_source_battery_reading_is_accurate());
        } else {
            buzzer_update(); // keep buzzer pattern responsive between LCD refreshes
        }

        vTaskDelay(pdMS_TO_TICKS(BUZZER_UPDATE_INTERVAL_MS));
    }
}

void app_main(void) {
    ESP_LOGI(TAG, "=== ColdWatch Firmware Boot (ESP32) ===");

    // Configure UART0 for the console command interface (Serial Monitor)
    uart_driver_install(UART_NUM_0, 256 * 2, 0, 0, NULL, 0);

    gpio_reset_pin(ACK_BUTTON_GPIO);
    gpio_set_direction(ACK_BUTTON_GPIO, GPIO_MODE_INPUT);
    gpio_set_pull_mode(ACK_BUTTON_GPIO, GPIO_PULLUP_ONLY);

    nvs_storage_init();          // SRS1_002/003/004/008, SRS2_002/003/004/008 (NVS config load)
    temperature_sensor_init();   // SRS1_001
    humidity_sensor_init();      // SRS2_001
    power_source_init();         // Main power-supply detection (GPIO34) + battery monitoring (GPIO35)
    buzzer_init();
    lcd_init();
    sms_module_init();
    alarm_manager_init();

    // SRS3_006: report any emergency snapshot saved during a previous
    // critical-battery event, so it can be recovered/inspected after reboot.
    {
        coldwatch_emergency_snapshot_t snap;
        if (nvs_storage_load_emergency_snapshot(&snap)) {
            ESP_LOGW(TAG, "Found emergency snapshot from a previous critical-battery event "
                          "(t=%lldms, batt=%u%%) - type SNAP to view",
                     snap.timestampMs, snap.batteryPercentage);
        }
    }

    printf("Type GET / LOG / POWER / SNAP / RESET / SET HIGH x / SET LOW x / SET RES x / SET HYST x /\n"
           "     SET HUMHIGH x / SET HUMLOW x / SET HUMRES x / SET HUMHYST x\n");

    xTaskCreate(console_task, "console_task", 4096, NULL, 5, NULL);
    xTaskCreate(coldwatch_task, "coldwatch_task", 4096, NULL, 5, NULL);
}
